__bundled["src.geometry"] = function()
local U = require('src.util')
local M = {}

local function dot2(a, b)
  return a.x * b.x + a.z * b.z
end

local function length2(value)
  return math.sqrt(value.x * value.x + value.z * value.z)
end

local function sub(a, b)
  return { x = a.x - b.x, y = (a.y or 0) - (b.y or 0), z = a.z - b.z }
end

local function addScaled(a, b, scale)
  return { x = a.x + b.x * scale, y = (a.y or 0) + (b.y or 0) * scale, z = a.z + b.z * scale }
end

function M.distance2(a, b)
  local x, z = a.x - b.x, a.z - b.z
  return math.sqrt(x * x + z * z)
end

function M.distance3(a, b)
  local x, y, z = a.x - b.x, (a.y or 0) - (b.y or 0), a.z - b.z
  return math.sqrt(x * x + y * y + z * z)
end

function M.signedAngleDelta(fromDeg, toDeg)
  return (toDeg - fromDeg + 540) % 360 - 180
end

function M.forwardFromLook(look)
  local length = length2(look)
  if length < 0.0001 then return { x = 0, y = 0, z = 1 } end
  return { x = look.x / length, y = 0, z = look.z / length }
end

function M.headingFromLook(look)
  local forward = M.forwardFromLook(look)
  local angle = -math.deg(math.atan2(forward.x, forward.z))
  return angle < 0 and angle + 360 or angle
end

function M.velocityHeading(velocity, fallback)
  if math.abs(velocity.x) < 1 and math.abs(velocity.z) < 1 then return fallback end
  local angle = -math.deg(math.atan2(velocity.x, velocity.z))
  return angle < 0 and angle + 360 or angle
end

function M.signedSlipAngle(look, velocity)
  local heading = M.headingFromLook(look)
  return M.signedAngleDelta(heading, M.velocityHeading(velocity, heading))
end

function M.offset(position, look, meters)
  local forward = M.forwardFromLook(look)
  return {
    x = position.x + forward.x * meters,
    y = position.y,
    z = position.z + forward.z * meters
  }
end

function M.insideCircle(point, center, radius)
  return M.distance2(point, center) <= radius
end

function M.crossedGate(previous, current, gate)
  local normal = M.forwardFromLook(gate.direction)
  local prev = sub(previous, gate.center)
  local nextValue = sub(current, gate.center)
  local prevSide = dot2(prev, normal)
  local nextSide = dot2(nextValue, normal)
  if prevSide > 0 or nextSide < 0 then return false end
  local t = math.abs(prevSide) / math.max(0.0001, math.abs(prevSide) + math.abs(nextSide))
  local crossing = {
    x = U.lerp(previous.x, current.x, t) - gate.center.x,
    y = 0,
    z = U.lerp(previous.z, current.z, t) - gate.center.z
  }
  local lateral = { x = -normal.z, y = 0, z = normal.x }
  return math.abs(dot2(crossing, lateral)) <= (gate.widthMeters or 14) * 0.5
end

function M.pointInPolygon(point, polygon)
  if #polygon < 3 then return false end
  local inside = false
  local j = #polygon
  for i = 1, #polygon do
    local pi, pj = polygon[i], polygon[j]
    local denominator = pj.z - pi.z
    if math.abs(denominator) < 0.00001 then denominator = denominator < 0 and -0.00001 or 0.00001 end
    local intersects = ((pi.z > point.z) ~= (pj.z > point.z))
      and point.x < (pj.x - pi.x) * (point.z - pi.z) / denominator + pi.x
    if intersects then inside = not inside end
    j = i
  end
  return inside
end

function M.distanceToSegment(point, a, b)
  local ab = sub(b, a)
  local lengthSquared = dot2(ab, ab)
  if lengthSquared <= 0.0001 then return M.distance2(point, a) end
  local t = U.clamp(dot2(sub(point, a), ab) / lengthSquared, 0, 1)
  return M.distance2(point, addScaled(a, ab, t))
end

function M.signedDistanceToPolygon(point, polygon)
  if #polygon < 3 then return -math.huge end
  local distance = math.huge
  for i = 1, #polygon do
    distance = math.min(distance, M.distanceToSegment(point, polygon[i], polygon[i % #polygon + 1]))
  end
  return M.pointInPolygon(point, polygon) and distance or -distance
end

function M.pathLength(path)
  local length = 0
  for i = 2, #path do length = length + M.distance2(path[i - 1], path[i]) end
  return length
end

function M.getProgress(path, point, firstSegment, lastSegment)
  if #path == 0 then return { meters = 0, distanceToPathMeters = 0, normalized = 0, segmentIndex = 0 } end
  if #path == 1 then
    return { meters = 0, distanceToPathMeters = M.distance2(path[1], point), normalized = 0, segmentIndex = 0 }
  end

  firstSegment = U.clamp(firstSegment or 0, 0, #path - 2)
  lastSegment = U.clamp(lastSegment or (#path - 2), firstSegment, #path - 2)
  local bestDistance, bestAlong, bestSegment = math.huge, 0, firstSegment
  local traversed = 0
  for luaIndex = 1, #path - 1 do
    local segmentIndex = luaIndex - 1
    local a, b = path[luaIndex], path[luaIndex + 1]
    local ab = sub(b, a)
    local length = length2(ab)
    if length > 0.0001 then
      if segmentIndex >= firstSegment and segmentIndex <= lastSegment then
        local t = U.clamp(dot2(sub(point, a), ab) / dot2(ab, ab), 0, 1)
        local closest = addScaled(a, ab, t)
        local distance = M.distance2(point, closest)
        if distance < bestDistance then
          bestDistance = distance
          bestAlong = traversed + length * t
          bestSegment = segmentIndex
        end
      end
      traversed = traversed + length
    end
  end

  if bestDistance == math.huge then bestDistance = M.distance2(path[1], point) end
  return {
    meters = bestAlong,
    distanceToPathMeters = bestDistance,
    normalized = traversed <= 0 and 0 or U.clamp(bestAlong / traversed, 0, 1),
    segmentIndex = bestSegment
  }
end

function M.createOffsetPath(path, offsetMeters, maxMiterMultiplier)
  if #path < 2 or math.abs(offsetMeters) <= 0.0001 then return U.copy(path) end
  maxMiterMultiplier = maxMiterMultiplier or 2
  local result = {}
  local maxMiter = math.abs(offsetMeters) * math.max(1, maxMiterMultiplier)

  local function direction(segment)
    local delta = sub(path[segment + 2], path[segment + 1])
    local length = length2(delta)
    return length <= 0.0001 and { x = 0, z = 1 } or { x = delta.x / length, z = delta.z / length }
  end

  for i = 1, #path do
    local previous = direction(math.max(0, i - 2))
    local following = direction(math.min(#path - 2, i - 1))
    local pNormal = { x = previous.z, z = -previous.x }
    local nNormal = { x = following.z, z = -following.x }
    local normal = { x = pNormal.x + nNormal.x, z = pNormal.z + nNormal.z }
    local normalLength = math.sqrt(normal.x * normal.x + normal.z * normal.z)
    if normalLength <= 0.0001 then normal, normalLength = nNormal, 1 end
    normal.x, normal.z = normal.x / normalLength, normal.z / normalLength
    local denominator = math.abs(normal.x * nNormal.x + normal.z * nNormal.z)
    local miter = math.min(math.abs(offsetMeters) / math.max(0.25, denominator), maxMiter)
    if offsetMeters < 0 then miter = -miter end
    result[i] = { x = path[i].x + normal.x * miter, y = path[i].y, z = path[i].z + normal.z * miter }
  end
  return result
end

return M

end

__bundled["src.profiles"] = function()
local U = require('src.util')
local D = require('src.defaults')
local M = {}

local overrideFields = {
  'targetSpeedKmh',
  'targetAngleDeg',
  'minimumAngleDeg',
  'styleMinimumDriftAngleDeg',
  'styleFullDriftAngleDeg'
}

local function wildcardPattern(pattern)
  local escaped = pattern:gsub('([%^%$%(%)%%%.%[%]%+%-])', '%%%1')
  return '^' .. escaped:gsub('%*', '.*'):gsub('%?', '.') .. '$'
end

local function patternKey(pattern)
  return tostring(pattern or ''):lower()
end

local function specificity(profile, carID, index)
  local pattern = tostring(profile.carModelPattern or '')
  if patternKey(pattern) == patternKey(carID) then return 1000000 + index end
  local plain = pattern:gsub('[%*%?]', '')
  return #plain * 1000 + index
end

local function matchingProfiles(layout, carID)
  local matches = {}
  for index, profile in ipairs(layout.carScoringProfiles or {}) do
    if M.matches(carID, profile.carModelPattern) then
      matches[#matches + 1] = {
        profile = profile,
        index = index,
        key = patternKey(profile.carModelPattern),
        score = specificity(profile, carID, index)
      }
    end
  end
  table.sort(matches, function(a, b) return a.score < b.score end)
  return matches
end

function M.matches(value, pattern)
  value, pattern = tostring(value or ''):lower(), tostring(pattern or ''):lower()
  if pattern == '' then return false end
  if value == pattern then return true end
  if not pattern:find('*', 1, true) and not pattern:find('?', 1, true) then
    return value:find(pattern, 1, true) ~= nil
  end
  return value:match(wildcardPattern(pattern)) ~= nil
end

function M.find(layout, carID)
  local matches = matchingProfiles(layout, carID)
  local match = matches[#matches]
  return match and match.profile or nil, match and match.index or nil
end

function M.findExact(layout, carID)
  return M.findPattern(layout, carID)
end

function M.findPattern(layout, pattern)
  for index, profile in ipairs(layout.carScoringProfiles or {}) do
    if patternKey(profile.carModelPattern) == patternKey(pattern) then
      return profile, index
    end
  end
  return nil, nil
end

local function apply(target, overrides)
  if type(overrides) ~= 'table' then return end
  for _, field in ipairs(overrideFields) do
    if overrides[field] ~= nil then target[field] = tonumber(overrides[field]) or target[field] end
  end
end

function M.resolve(layout, carID)
  local result = U.copy(D.scoring)
  apply(result, layout.scoringOverrides)
  local profile = nil
  for _, match in ipairs(matchingProfiles(layout, carID)) do
    profile = match.profile
    apply(result, profile.overrides)
  end
  return result, profile
end

function M.resolveInherited(layout, carID, targetPattern)
  local result = U.copy(D.scoring)
  apply(result, layout.scoringOverrides)
  local targetScore = specificity({ carModelPattern = targetPattern }, carID, 0)
  local targetKey = patternKey(targetPattern)
  for _, match in ipairs(matchingProfiles(layout, carID)) do
    if match.key ~= targetKey and match.score < targetScore then
      apply(result, match.profile.overrides)
    end
  end
  return result
end

function M.detectPackPattern(carID)
  local text = tostring(carID or '')
  local prefix = text:match('^([^_]+_)')
  if not prefix then return nil, nil end
  local name = prefix:gsub('_$', ''):upper()
  return prefix .. '*', name .. ' Pack'
end

function M.ensurePattern(layout, pattern, name)
  layout.carScoringProfiles = U.ensureArray(layout.carScoringProfiles)
  local profile, index = M.findPattern(layout, pattern)
  if profile then return profile, index end
  profile = {
    name = name or pattern,
    carModelPattern = pattern,
    overrides = {}
  }
  table.insert(layout.carScoringProfiles, 1, profile)
  return profile, 1
end

function M.ensureExact(layout, carID)
  return M.ensurePattern(layout, carID, carID)
end

function M.setOverrideForPattern(layout, pattern, name, field, value)
  local profile, index = M.ensurePattern(layout, pattern, name)
  profile.overrides = U.ensureTable(profile.overrides)
  profile.overrides[field] = value ~= nil and tonumber(value) or nil
  if value == nil then
    local hasOverrides = false
    for _, overrideField in ipairs(overrideFields) do
      if profile.overrides[overrideField] ~= nil then
        hasOverrides = true
        break
      end
    end
    if not hasOverrides then
      table.remove(layout.carScoringProfiles, index)
      return nil
    end
  end
  return profile
end

function M.setOverride(layout, carID, field, value)
  return M.setOverrideForPattern(layout, carID, carID, field, value)
end

function M.validate(scoring)
  if scoring.minimumAngleDeg < 0 then return false, 'O ângulo mínimo tem de ser pelo menos zero.' end
  if scoring.targetAngleDeg <= scoring.minimumAngleDeg then
    return false, 'O ângulo alvo tem de ser maior que o ângulo mínimo.'
  end
  if scoring.targetSpeedKmh <= 0 then return false, 'A velocidade alvo tem de ser maior que zero.' end
  if scoring.styleMinimumDriftAngleDeg < 0 then
    return false, 'O ângulo mínimo de estilo tem de ser pelo menos zero.'
  end
  if scoring.styleFullDriftAngleDeg <= scoring.styleMinimumDriftAngleDeg then
    return false, 'O ângulo total de estilo tem de ser maior que o ângulo mínimo de estilo.'
  end
  return true
end

M.overrideFields = overrideFields
return M

end

__bundled["src.model"] = function()
local U = require('src.util')
local D = require('src.defaults')
local P = require('src.profiles')
local M = {}

local function normalizeStart(value)
  if type(value) ~= 'table' then return nil end
  value.position = U.vec(value.position)
  value.direction = U.vec(value.direction, { x = 0, y = 0, z = 1 })
  value.radiusMeters = tonumber(value.radiusMeters) or D.editor.startRadiusMeters
  return value
end

local function normalizeGate(value)
  if type(value) ~= 'table' then return nil end
  value.center = U.vec(value.center)
  value.direction = U.vec(value.direction, { x = 0, y = 0, z = 1 })
  value.widthMeters = tonumber(value.widthMeters) or D.editor.finishWidthMeters
  return value
end

local function canonicalPattern(pattern)
  local text = tostring(pattern or '')
  if text ~= '' and not text:find('*', 1, true) and not text:find('?', 1, true)
    and text:sub(-1) == '_' then
    return text .. '*'
  end
  return text
end

local function patternName(pattern, fallback)
  fallback = tostring(fallback or '')
  local prefix = tostring(pattern or ''):match('^([^*?]+_)%*$')
  if prefix then return prefix:gsub('_$', ''):upper() .. ' Pack' end
  return fallback ~= '' and fallback or tostring(pattern or '')
end

local function cleanOverrides(overrides)
  local result = {}
  if type(overrides) ~= 'table' then return result end
  for _, field in ipairs(P.overrideFields) do
    if overrides[field] ~= nil then result[field] = tonumber(overrides[field]) or overrides[field] end
  end
  return result
end

local function hasOverrides(overrides)
  if type(overrides) ~= 'table' then return false end
  for _, field in ipairs(P.overrideFields) do
    if overrides[field] ~= nil then return true end
  end
  return false
end

local function normalizeProfiles(layout)
  local profiles, byKey = {}, {}
  for _, profile in ipairs(U.ensureArray(layout.carScoringProfiles)) do
    if type(profile) == 'table' then
      local pattern = canonicalPattern(profile.carModelPattern or profile.name)
      if pattern ~= '' then
        local key = pattern:lower()
        local existing = byKey[key]
        if not existing then
          existing = {
            name = patternName(pattern, profile.name),
            carModelPattern = pattern,
            overrides = cleanOverrides(profile.overrides)
          }
          profiles[#profiles + 1] = existing
          byKey[key] = existing
        elseif not hasOverrides(existing.overrides) then
          existing.overrides = cleanOverrides(profile.overrides)
        end
      end
    end
  end

  for tag, overrides in pairs(U.ensureTable(layout.taggedScoringOverrides)) do
    local pattern = canonicalPattern(tag)
    local key = pattern:lower()
    if pattern ~= '' and not byKey[key] and hasOverrides(overrides) then
      local profile = {
        name = patternName(pattern, tag),
        carModelPattern = pattern,
        overrides = cleanOverrides(overrides)
      }
      profiles[#profiles + 1] = profile
      byKey[key] = profile
    end
  end

  layout.carScoringProfiles = profiles
end

local function copyStart(value)
  if not value then return nil end
  return {
    position = U.copy(value.position),
    radiusMeters = value.radiusMeters,
    direction = U.copy(value.direction)
  }
end

local function copyGate(value)
  if not value then return nil end
  return {
    center = U.copy(value.center),
    direction = U.copy(value.direction),
    widthMeters = value.widthMeters
  }
end

local function cleanProfiles(profiles)
  local result = {}
  for _, profile in ipairs(profiles or {}) do
    if hasOverrides(profile.overrides) then
      result[#result + 1] = {
        name = tostring(profile.name or profile.carModelPattern or ''),
        carModelPattern = tostring(profile.carModelPattern or ''),
        overrides = cleanOverrides(profile.overrides)
      }
    end
  end
  return result
end

function M.normalizeLayout(layout, track, layoutID)
  layout = type(layout) == 'table' and layout or D.newLayout(track, layoutID)
  layout.version = 5
  layout.track = tostring(layout.track or track or '')
  layout.layout = tostring(layout.layout or layoutID or 'open')
  layout.pathCorridorHalfWidthMeters = tonumber(layout.pathCorridorHalfWidthMeters)
    or D.editor.defaultPathCorridorHalfWidthMeters
  layout.scoringOverrides = U.ensureTable(layout.scoringOverrides)
  layout.taggedScoringOverrides = U.ensureTable(layout.taggedScoringOverrides)
  layout.leadStart = normalizeStart(layout.leadStart)
  layout.chaseStart = normalizeStart(layout.chaseStart)
  layout.soloStart = normalizeStart(layout.soloStart)
  layout.finishGate = normalizeGate(layout.finishGate)
  layout.pathWaypoints = U.ensureArray(layout.pathWaypoints)
  for index, point in ipairs(layout.pathWaypoints) do layout.pathWaypoints[index] = U.vec(point) end
  layout.outerZones = U.ensureArray(layout.outerZones)
  for _, zone in ipairs(layout.outerZones) do
    zone.name = tostring(zone.name or '')
    zone.points = U.ensureArray(zone.points)
    for index, point in ipairs(zone.points) do zone.points[index] = U.vec(point) end
  end
  layout.innerClips = U.ensureArray(layout.innerClips)
  for _, clip in ipairs(layout.innerClips) do
    clip.name = tostring(clip.name or '')
    clip.position = U.vec(clip.position)
    clip.radiusMeters = tonumber(clip.radiusMeters) or D.editor.clipRadiusMeters
  end
  layout.lineupPairs = U.ensureArray(layout.lineupPairs)
  normalizeProfiles(layout)
  return layout
end

function M.validateLayout(layout)
  local errors = {}
  if not layout.leadStart then errors[#errors + 1] = 'Falta a partida.' end
  if not layout.finishGate then errors[#errors + 1] = 'Falta o gate de chegada.' end
  if #layout.pathWaypoints < 2 then errors[#errors + 1] = 'São necessários pelo menos dois pontos de rota.' end
  if layout.pathCorridorHalfWidthMeters <= 0 then errors[#errors + 1] = 'A meia-largura da rota tem de ser maior que zero.' end
  for index, zone in ipairs(layout.outerZones) do
    if #zone.points < 3 then errors[#errors + 1] = 'A zona exterior ' .. index .. ' precisa de pelo menos três pontos.' end
  end
  for index, clip in ipairs(layout.innerClips) do
    if clip.radiusMeters <= 0 then errors[#errors + 1] = 'O raio do clip interior ' .. index .. ' tem de ser maior que zero.' end
  end
  local scoring = P.resolve(layout, '')
  local ok, errorMessage = P.validate(scoring)
  if not ok then errors[#errors + 1] = errorMessage end
  return errors
end

function M.isReady(layout)
  return layout.leadStart ~= nil and layout.finishGate ~= nil and #layout.pathWaypoints >= 2
end

function M.toStorageLayout(layout)
  layout = M.normalizeLayout(U.copy(layout), layout.track, layout.layout)
  local result = {
    version = 5,
    track = layout.track,
    layout = layout.layout,
    pathCorridorHalfWidthMeters = layout.pathCorridorHalfWidthMeters,
    scoringOverrides = cleanOverrides(layout.scoringOverrides),
    carScoringProfiles = cleanProfiles(layout.carScoringProfiles),
    leadStart = copyStart(layout.leadStart),
    finishGate = copyGate(layout.finishGate),
    pathWaypoints = U.copy(layout.pathWaypoints),
    outerZones = U.copy(layout.outerZones),
    innerClips = U.copy(layout.innerClips)
  }
  return result
end

return M

end

__bundled["src.results"] = function()
local U = require('src.util')
local M = {}

function M.normalize(value, track, layoutID, carID)
  value = type(value) == 'table' and value or {}
  value.version = 1
  value.track = track
  value.layout = layoutID
  value.car = carID
  value.personalBest = type(value.personalBest) == 'table' and value.personalBest or nil
  value.runs = U.ensureArray(value.runs)
  while #value.runs > 50 do table.remove(value.runs) end
  return value
end

function M.add(results, score, track, layoutID, carID, timestamp)
  local record = U.copy(score)
  -- Guarded: the online-script sandbox may not expose os.time.
  if not timestamp and os and os.time then
    local ok, now = pcall(os.time)
    timestamp = ok and now or nil
  end
  record.dateUtc = timestamp or 0
  record.track = track
  record.layout = layoutID
  record.car = carID
  record.personalBest = false
  if record.valid and (not results.personalBest or record.score > results.personalBest.score) then
    record.personalBest = true
    results.personalBest = U.copy(record)
  end
  table.insert(results.runs, 1, record)
  while #results.runs > 50 do table.remove(results.runs) end
  return record
end

function M.clear(results)
  results.personalBest = nil
  results.runs = {}
end

return M

end

__bundled["src.scoring"] = function()
local U = require('src.util')
local G = require('src.geometry')
local M = {}

local function average(items, selector)
  if #items == 0 then return 0 end
  local total = 0
  for _, item in ipairs(items) do total = total + selector(item) end
  return total / #items
end

local function interpolateVector(a, b, t)
  return {
    x = U.lerp(a.x, b.x, t),
    y = U.lerp(a.y or 0, b.y or 0, t),
    z = U.lerp(a.z, b.z, t)
  }
end

local function interpolate(a, b, t, targetProgress, pathLength, layout)
  local position = interpolateVector(a.position, b.position, t)
  local projected = G.getProgress(layout.pathWaypoints, position)
  local signedAngle = a.signedAngleDeg + G.signedAngleDelta(a.signedAngleDeg, b.signedAngleDeg) * t
  return {
    timeMilliseconds = U.round(U.lerp(a.timeMilliseconds, b.timeMilliseconds, t)),
    position = position,
    look = interpolateVector(a.look, b.look, t),
    velocity = interpolateVector(a.velocity, b.velocity, t),
    steerAngle = U.round(U.clamp(U.lerp(a.steerAngle, b.steerAngle, t), 0, 255)),
    gas = U.round(U.clamp(U.lerp(a.gas, b.gas, t), 0, 255)),
    signedAngleDeg = signedAngle,
    angleDeg = math.abs(signedAngle),
    speedKmh = U.lerp(a.speedKmh, b.speedKmh, t),
    progress = {
      meters = targetProgress,
      distanceToPathMeters = projected.distanceToPathMeters,
      normalized = pathLength <= 0 and 0 or U.clamp(targetProgress / pathLength, 0, 1),
      segmentIndex = projected.segmentIndex
    },
    frontBumper = interpolateVector(a.frontBumper, b.frontBumper, t),
    rearBumper = interpolateVector(a.rearBumper, b.rearBumper, t),
    rearWheelLeft = interpolateVector(a.rearWheelLeft, b.rearWheelLeft, t),
    rearWheelRight = interpolateVector(a.rearWheelRight, b.rearWheelRight, t),
    rearWheelLeftExact = a.rearWheelLeftExact and b.rearWheelLeftExact,
    rearWheelRightExact = a.rearWheelRightExact and b.rearWheelRightExact,
    exactWheelCoverage = (a.rearWheelLeftExact and b.rearWheelLeftExact and 0.5 or 0)
      + (a.rearWheelRightExact and b.rearWheelRightExact and 0.5 or 0)
  }
end

function M.resampleByProgress(samples, layout, binMeters)
  if #samples == 0 then return {} end
  binMeters = math.max(0.1, binMeters)
  local ordered = U.copy(samples)
  table.sort(ordered, function(a, b) return a.timeMilliseconds < b.timeMilliseconds end)
  local monotonic = {}
  for _, sample in ipairs(ordered) do
    if #monotonic == 0 or sample.progress.meters >= monotonic[#monotonic].progress.meters then
      monotonic[#monotonic + 1] = sample
    end
  end
  if #monotonic < 2 then return monotonic end

  local firstProgress = monotonic[1].progress.meters
  local lastProgress = firstProgress
  for _, sample in ipairs(monotonic) do lastProgress = math.max(lastProgress, sample.progress.meters) end
  local firstTarget = math.ceil(firstProgress / binMeters) * binMeters
  local lastTarget = math.floor(lastProgress / binMeters) * binMeters
  if lastTarget < firstTarget then return { monotonic[1] } end

  local result, upperIndex = {}, 2
  local pathLength = G.pathLength(layout.pathWaypoints)
  local target = firstTarget
  while target <= lastTarget + 0.001 do
    while upperIndex < #monotonic and monotonic[upperIndex].progress.meters < target do
      upperIndex = upperIndex + 1
    end
    local lower, upper = monotonic[math.max(1, upperIndex - 1)], monotonic[upperIndex]
    local span = upper.progress.meters - lower.progress.meters
    local t = span <= 0.001 and 0 or U.clamp((target - lower.progress.meters) / span, 0, 1)
    result[#result + 1] = interpolate(lower, upper, t, target, pathLength, layout)
    target = target + binMeters
  end
  return result
end

local function courseBins(bins, layout, config)
  local pathLength = G.pathLength(layout.pathWaypoints)
  local startAt = config.startExclusionMeters
  local endAt = math.max(startAt, pathLength - config.finishExclusionMeters)
  local result = {}
  for _, sample in ipairs(bins) do
    if sample.progress.meters >= startAt and sample.progress.meters <= endAt then result[#result + 1] = sample end
  end
  return #result > 0 and result or bins
end

local function zoneSector(zone, layout, binMeters)
  if #zone.points == 0 then return { startAt = 0, endAt = 0 } end
  local startAt, endAt = math.huge, -math.huge
  for _, point in ipairs(zone.points) do
    local meters = G.getProgress(layout.pathWaypoints, point).meters
    startAt, endAt = math.min(startAt, meters), math.max(endAt, meters)
  end
  local minimumSpan = math.max(2, binMeters * 2)
  if endAt - startAt < minimumSpan then
    local center = (startAt + endAt) * 0.5
    startAt, endAt = center - minimumSpan * 0.5, center + minimumSpan * 0.5
  end
  return { startAt = startAt, endAt = endAt }
end

local function featureSectors(layout, config)
  local pathLength = G.pathLength(layout.pathWaypoints)
  local sectors = {}
  for _, zone in ipairs(layout.outerZones) do
    local sector = zoneSector(zone, layout, config.progressBinMeters)
    sectors[#sectors + 1] = {
      startAt = math.max(0, sector.startAt - config.judgedFeatureWindowMeters),
      endAt = math.min(pathLength, sector.endAt + config.judgedFeatureWindowMeters)
    }
  end
  for _, clip in ipairs(layout.innerClips) do
    local center = G.getProgress(layout.pathWaypoints, clip.position).meters
    sectors[#sectors + 1] = {
      startAt = math.max(0, center - config.judgedFeatureWindowMeters),
      endAt = math.min(pathLength, center + config.judgedFeatureWindowMeters)
    }
  end
  table.sort(sectors, function(a, b) return a.startAt < b.startAt end)
  local merged = {}
  for _, sector in ipairs(sectors) do
    local previous = merged[#merged]
    if previous and sector.startAt <= previous.endAt then
      previous.endAt = math.max(previous.endAt, sector.endAt)
    else
      merged[#merged + 1] = sector
    end
  end
  return merged
end

local function activeDriftBins(course, layout, config)
  local sectors = featureSectors(layout, config)
  local judged = {}
  for _, sample in ipairs(course) do
    local include = #sectors == 0
    for _, sector in ipairs(sectors) do
      if sample.progress.meters >= sector.startAt and sample.progress.meters <= sector.endAt then
        include = true
        break
      end
    end
    if include then judged[#judged + 1] = sample end
  end
  if #judged == 0 then judged = U.copy(course) end
  if #judged < 2 or config.transitionGraceMeters <= 0 then return judged end

  local transitions, previous = {}, nil
  for _, sample in ipairs(judged) do
    if math.abs(sample.signedAngleDeg) >= config.minimumAngleDeg * 0.5 then
      if previous and ((previous.signedAngleDeg < 0) ~= (sample.signedAngleDeg < 0)) then
        transitions[#transitions + 1] = (previous.progress.meters + sample.progress.meters) * 0.5
      end
      previous = sample
    end
  end

  local active = {}
  for _, sample in ipairs(judged) do
    local include = true
    for _, transition in ipairs(transitions) do
      if math.abs(sample.progress.meters - transition) <= config.transitionGraceMeters then
        include = false
        break
      end
    end
    if include then active[#active + 1] = sample end
  end
  return #active > 0 and active or judged
end

function M.pathCorridorQuality(distanceToRoute, halfWidth, tolerance)
  local outside = math.max(0, distanceToRoute - math.max(0, halfWidth))
  if outside <= 0 then return 1 end
  return 1 - U.clamp(outside / math.max(0.001, tolerance), 0, 1)
end

function M.zonePointQuality(signedDistance, config)
  if signedDistance >= config.outerZoneFullDepthMeters then return 1 end
  if signedDistance >= 0 then
    local depth = signedDistance / config.outerZoneFullDepthMeters
    return config.outerZoneBoundaryQuality + (1 - config.outerZoneBoundaryQuality) * depth
  end
  local outside = -signedDistance
  if outside >= config.outerZoneOutsideToleranceMeters then return 0 end
  return config.outerZoneBoundaryQuality * (1 - outside / config.outerZoneOutsideToleranceMeters)
end

local function pathQuality(bins, layout, config)
  return average(bins, function(sample)
    return M.pathCorridorQuality(
      sample.progress.distanceToPathMeters,
      layout.pathCorridorHalfWidthMeters,
      config.pathCorridorOutsideToleranceMeters)
  end)
end

local function outerZoneQuality(bins, layout, config)
  if #layout.outerZones == 0 then return { average = 1, items = {} } end
  local items = {}
  for _, zone in ipairs(layout.outerZones) do
    local sector = zoneSector(zone, layout, config.progressBinMeters)
    local zoneBins = {}
    for _, sample in ipairs(bins) do
      local left = G.getProgress(layout.pathWaypoints, sample.rearWheelLeft).meters
      local right = G.getProgress(layout.pathWaypoints, sample.rearWheelRight).meters
      if (left >= sector.startAt and left <= sector.endAt)
        or (right >= sector.startAt and right <= sector.endAt) then
        zoneBins[#zoneBins + 1] = sample
      end
    end
    if #zoneBins == 0 then
      items[#items + 1] = 0
    else
      local qualities, entered = {}, false
      for _, sample in ipairs(zoneBins) do
        local left = G.signedDistanceToPolygon(sample.rearWheelLeft, zone.points)
        local right = G.signedDistanceToPolygon(sample.rearWheelRight, zone.points)
        local closest = math.max(left, right)
        entered = entered or closest >= 0
        qualities[#qualities + 1] = M.zonePointQuality(closest, config)
      end
      if not entered then
        items[#items + 1] = 0
      else
        local window = math.min(config.outerZoneBestAdjacentBins, #qualities)
        local placement = 0
        for startIndex = 1, #qualities - window + 1 do
          local total = 0
          for offset = 0, window - 1 do total = total + qualities[startIndex + offset] end
          placement = math.max(placement, total / window)
        end
        local covered = 0
        for _, quality in ipairs(qualities) do
          if quality >= config.outerZoneCoverageQualityThreshold then covered = covered + 1 end
        end
        local hold = U.clamp(
          (covered / #qualities) / math.max(0.01, config.outerZoneFullHoldCoverage), 0, 1)
        local weight = config.outerZonePlacementWeight + config.outerZoneHoldWeight
        items[#items + 1] = weight <= 0 and placement
          or (placement * config.outerZonePlacementWeight + hold * config.outerZoneHoldWeight) / weight
      end
    end
  end
  local total = 0
  for _, quality in ipairs(items) do total = total + quality end
  return { average = total / #items, items = items }
end

local function qualityFromDistance(distance, perfect, maximum)
  if distance <= perfect then return 1 end
  return 1 - U.clamp((distance - perfect) / math.max(0.001, maximum - perfect), 0, 1)
end

local function innerClipQuality(bins, layout, config)
  if #layout.innerClips == 0 then return { average = 1, items = {} } end
  local items = {}
  for _, clip in ipairs(layout.innerClips) do
    local center = G.getProgress(layout.pathWaypoints, clip.position).meters
    local qualities = {}
    for _, sample in ipairs(bins) do
      local frontProgress = G.getProgress(layout.pathWaypoints, sample.frontBumper).meters
      if math.abs(frontProgress - center) <= config.innerClipWindowMeters then
        local outside = math.max(0, G.distance3(sample.frontBumper, clip.position) - clip.radiusMeters)
        qualities[#qualities + 1] = {
          progress = sample.progress.meters,
          quality = qualityFromDistance(outside, 0, config.innerClipMaxDistanceMeters)
        }
      end
    end
    table.sort(qualities, function(a, b) return a.progress < b.progress end)
    local window = math.min(config.innerClipAdjacentBins, #qualities)
    local best = 0
    if window > 0 then
      for startIndex = 1, #qualities - window + 1 do
        local total = 0
        for offset = 0, window - 1 do total = total + qualities[startIndex + offset].quality end
        best = math.max(best, total / window)
      end
    end
    items[#items + 1] = best
  end
  local total = 0
  for _, quality in ipairs(items) do total = total + quality end
  return { average = total / #items, items = items }
end

-- Line (Drift Masters 1.7): points are spread across the outer zones and
-- inner clips, each an equal share; missing one scores 0 for it. Leaving the
-- drawn route ("off line") takes up to lineOffLineWeight of the line.
local function lineQuality(pathValue, zones, clips, config)
  local total, count = 0, 0
  for _, quality in ipairs(zones.items) do total, count = total + quality, count + 1 end
  for _, quality in ipairs(clips.items) do total, count = total + quality, count + 1 end
  if count == 0 then return pathValue end
  local weight = U.clamp(config.lineOffLineWeight, 0, 1)
  return (total / count) * (1 - weight) + pathValue * weight
end

local function angleQuality(bins, config)
  return average(bins, function(sample)
    return U.clamp(
      (sample.angleDeg - config.minimumAngleDeg)
      / math.max(0.001, config.targetAngleDeg - config.minimumAngleDeg), 0, 1)
  end)
end

local function engagement(bins, config)
  return average(bins, function(sample)
    return U.clamp(
      (sample.angleDeg - config.styleMinimumDriftAngleDeg)
      / math.max(0.001, config.styleFullDriftAngleDeg - config.styleMinimumDriftAngleDeg), 0, 1)
  end)
end

local function normalizedCorrection(delta, deadband, range)
  return U.clamp((delta - deadband) / math.max(0.001, range), 0, 1)
end

local function sign(value) return value < 0 and -1 or 1 end

-- Initiation (5): early (reference: the start exclusion, like the
-- initiation cones), rate to angle (how fast the desired angle is reached)
-- and smooth (no angle given back). A drop out of the drift and a second
-- initiation inside the window is a double initiation.
local function initiationQuality(bins, config)
  local startAt
  for index, sample in ipairs(bins) do
    if sample.angleDeg >= config.minimumAngleDeg then startAt = index break end
  end
  if not startAt then return { combined = 0, early = 0, rate = 0, smooth = 0, double = false, meters = nil } end
  local initiated = bins[startAt]
  local meters, side = initiated.progress.meters, sign(initiated.signedAngleDeg)
  local lateBy = meters - config.startExclusionMeters - config.initiationFullMeters
  local early = 1 - U.clamp(lateBy / math.max(0.001, config.initiationZeroMeters - config.initiationFullMeters), 0, 1)

  local rateAngle = config.targetAngleDeg * config.initiationRateAngleShare
  local reachedAfter, drop, dropped, double = nil, 0, false, false
  for index = startAt, #bins do
    local sample, previous = bins[index], bins[index - 1]
    if sample.progress.meters - meters > config.initiationWindowMeters then break end
    if not reachedAfter and sample.angleDeg >= rateAngle then reachedAfter = sample.progress.meters - meters end
    if sign(sample.signedAngleDeg) == side then
      if previous and index > startAt and sign(previous.signedAngleDeg) == side then
        drop = drop + math.max(0, previous.angleDeg - sample.angleDeg - config.angleChangeDeadbandDeg)
      end
      if sample.angleDeg < config.minimumAngleDeg * 0.5 then dropped = true end
      if dropped and sample.angleDeg >= config.minimumAngleDeg then double = true end
    end
  end
  local rate = reachedAfter and 1 - U.clamp((reachedAfter - config.initiationRateFullMeters)
    / math.max(0.001, config.initiationRateZeroMeters - config.initiationRateFullMeters), 0, 1) or 0
  local smooth = 1 - U.clamp(drop / math.max(0.001, config.initiationSmoothDropRangeDeg), 0, 1)
  local combined = (early + rate + smooth) / 3
  if double then combined = combined * config.doubleInitiationFactor end
  return { combined = combined, early = early, rate = rate, smooth = smooth, double = double, meters = meters }
end

-- Transitions (fluidity): each switch from one drift direction to the other,
-- scored on how quickly it rotates (meters spent below the minimum angle)
-- and on going from high angle to high angle (lock to lock).
local function transitionQuality(bins, config)
  local items, last = {}, nil
  for index, sample in ipairs(bins) do
    if sample.angleDeg >= config.minimumAngleDeg then
      if last and sign(bins[last].signedAngleDeg) ~= sign(sample.signedAngleDeg) then
        local fromMeters, toMeters = bins[last].progress.meters, sample.progress.meters
        local gap = toMeters - fromMeters
        local quick = 1 - U.clamp((gap - config.transitionFullMeters)
          / math.max(0.001, config.transitionZeroMeters - config.transitionFullMeters), 0, 1)
        local before, after = 0, 0
        for _, other in ipairs(bins) do
          local at = other.progress.meters
          if at <= fromMeters and fromMeters - at <= config.transitionLockWindowMeters then before = math.max(before, other.angleDeg) end
          if at >= toMeters and at - toMeters <= config.transitionLockWindowMeters then after = math.max(after, other.angleDeg) end
        end
        local lock = U.clamp((math.min(before, after) - config.minimumAngleDeg)
          / math.max(0.001, config.targetAngleDeg - config.minimumAngleDeg), 0, 1)
        items[#items + 1] = (quick + lock) * 0.5
      end
      last = index
    end
  end
  if #items == 0 then return nil end
  return average(items, function(item) return item end)
end

-- Fluidity (10): the car settled and flowing (few abrupt steering, throttle
-- and angle corrections), plus smooth lock-to-lock transitions where the
-- course has them. Commitment (5): pace, keeping it (no big speed drops)
-- and consistent throttle.
local function styleQuality(active, course, config)
  local pace = average(active, function(sample)
    return U.clamp(sample.speedKmh / config.targetSpeedKmh, 0, 1)
  end)
  local settled = 1
  if #active >= 2 then
    settled = 0
    for i = 2, #active do
      local steer = normalizedCorrection(
        math.abs(active[i].steerAngle - active[i - 1].steerAngle),
        config.steeringDeadband, config.steeringCorrectionRange)
      local throttle = normalizedCorrection(
        math.abs(active[i].gas - active[i - 1].gas),
        config.throttleDeadband, config.throttleCorrectionRange)
      local angle = normalizedCorrection(
        math.abs(G.signedAngleDelta(active[i - 1].signedAngleDeg, active[i].signedAngleDeg)),
        config.angleChangeDeadbandDeg, config.angleCorrectionRangeDeg)
      settled = settled + 1 - U.clamp(steer * 0.40 + throttle * 0.25 + angle * 0.35, 0, 1)
    end
    settled = settled / (#active - 1)
  end
  local transitions = transitionQuality(course, config)
  local fluidity = transitions == nil and settled
    or settled * (1 - config.fluidityTransitionWeight) + transitions * config.fluidityTransitionWeight

  local speeds = {}
  for _, sample in ipairs(active) do speeds[#speeds + 1] = sample.speedKmh end
  table.sort(speeds)
  local consistency = 1
  if #speeds > 0 then
    local mean = average(active, function(sample) return sample.speedKmh end)
    local low = speeds[math.max(1, math.floor(#speeds * 0.10))]
    consistency = 1 - U.clamp((mean - low) / math.max(1, mean) / math.max(0.001, config.commitmentDropRange), 0, 1)
  end
  local throttleOn = average(active, function(sample)
    return sample.gas >= config.commitmentThrottleOn * 255 and 1 or 0
  end)
  local throttle = U.clamp(throttleOn / math.max(0.001, config.commitmentFullThrottleShare), 0, 1)
  local weights = config.commitmentPaceWeight + config.commitmentConsistencyWeight + config.commitmentThrottleWeight
  local commitment = weights <= 0 and pace or (pace * config.commitmentPaceWeight
    + consistency * config.commitmentConsistencyWeight + throttle * config.commitmentThrottleWeight) / weights
  return {
    speed = pace, fluidity = fluidity, settled = settled, transitions = transitions,
    commitment = commitment, consistency = consistency, throttle = throttle
  }
end

local function percentageItems(items)
  local result = {}
  for _, item in ipairs(items) do result[#result + 1] = item * 100 end
  return result
end

function M.zero(reason)
  return {
    score = 0, line = 0, angle = 0, styleSpeed = 0, penalties = 0,
    initiation = 0, fluidity = 0, commitment = 0, initiationQuality = 0, initiationMeters = nil,
    doubleInitiation = false,
    averageAngle = 0, averageSpeed = 0, maxAngle = 0,
    targetAngle = 0, targetSpeed = 0, pathQuality = 0, zoneQuality = 0,
    clipQuality = 0, zoneQualities = {}, clipQualities = {},
    angleQuality = 0, speedQuality = 0, fluidityQuality = 0,
    exactWheelCoverage = 0, valid = false, reason = reason or 'Inválida'
  }
end

function M.scoreLead(samples, layout, config, penalties, invalid, reason)
  penalties = penalties or 0
  if invalid or #samples == 0 then return M.zero(reason) end
  local bins = M.resampleByProgress(samples, layout, config.progressBinMeters)
  if #bins == 0 then return M.zero('Sem amostras do percurso') end
  local course = courseBins(bins, layout, config)
  local active = activeDriftBins(course, layout, config)
  local path = pathQuality(course, layout, config)
  local zones = outerZoneQuality(bins, layout, config)
  local clips = innerClipQuality(bins, layout, config)
  local lineValue = lineQuality(path, zones, clips, config)
  local angleValue = angleQuality(active, config)
  local style = styleQuality(active, course, config)
  local engaged = engagement(active, config)
  local start = initiationQuality(bins, config)
  local line = config.leadLinePoints * lineValue
  local angle = config.leadAnglePoints * angleValue
  -- Style splits into its three parts; fluidity and commitment only count
  -- while actually drifting (engagement), initiation measures the drift's start.
  local initiation = config.styleInitiationPoints * start.combined
  local fluidity = config.styleFluidityPoints * style.fluidity * engaged
  local commitment = config.styleCommitmentPoints * style.commitment * engaged
  local styleParts = config.styleInitiationPoints + config.styleFluidityPoints + config.styleCommitmentPoints
  local styleSpeed = styleParts <= 0 and 0
    or (initiation + fluidity + commitment) * config.leadStyleSpeedPoints / styleParts
  local maxAngle = 0
  for _, sample in ipairs(bins) do maxAngle = math.max(maxAngle, sample.angleDeg) end
  return {
    score = U.clamp(line + angle + styleSpeed - penalties, 0, 100),
    line = line,
    angle = angle,
    styleSpeed = styleSpeed,
    initiation = initiation,
    fluidity = fluidity,
    commitment = commitment,
    initiationQuality = start.combined * 100,
    initiationMeters = start.meters,
    doubleInitiation = start.double,
    penalties = penalties,
    averageAngle = average(active, function(sample) return sample.angleDeg end),
    averageSpeed = average(active, function(sample) return sample.speedKmh end),
    maxAngle = maxAngle,
    targetAngle = config.targetAngleDeg,
    targetSpeed = config.targetSpeedKmh,
    pathQuality = path * 100,
    zoneQuality = zones.average * 100,
    clipQuality = clips.average * 100,
    zoneQualities = percentageItems(zones.items),
    clipQualities = percentageItems(clips.items),
    angleQuality = angleValue * 100,
    speedQuality = style.speed * engaged * 100,
    fluidityQuality = style.fluidity * engaged * 100,
    exactWheelCoverage = average(bins, function(sample) return sample.exactWheelCoverage or 0 end) * 100,
    valid = true,
    reason = 'Válida'
  }
end

local function statistics(values)
  table.sort(values)
  if #values == 0 then return { minimum = 0, average = 0, median = 0, percentile75 = 0, maximum = 0 } end
  local total = 0
  for _, value in ipairs(values) do total = total + value end
  local function percentile(fraction)
    if #values == 1 then return values[1] end
    local position = U.clamp(fraction, 0, 1) * (#values - 1)
    local lower = math.floor(position) + 1
    local upper = math.ceil(position) + 1
    return lower == upper and values[lower] or U.lerp(values[lower], values[upper], position - math.floor(position))
  end
  return {
    minimum = values[1],
    average = total / #values,
    median = percentile(0.5),
    percentile75 = percentile(0.75),
    maximum = values[#values]
  }
end

function M.analyzeRun(samples, layout, config)
  local bins = M.resampleByProgress(samples, layout, config.progressBinMeters)
  local course = courseBins(bins, layout, config)
  local active = activeDriftBins(course, layout, config)
  local courseSpeeds, courseAngles, speeds, angles = {}, {}, {}, {}
  for _, sample in ipairs(course) do
    courseSpeeds[#courseSpeeds + 1] = sample.speedKmh
    courseAngles[#courseAngles + 1] = sample.angleDeg
  end
  for _, sample in ipairs(active) do
    speeds[#speeds + 1] = sample.speedKmh
    angles[#angles + 1] = sample.angleDeg
  end
  return {
    durationMilliseconds = #samples < 2 and 0
      or math.max(0, samples[#samples].timeMilliseconds - samples[1].timeMilliseconds),
    rawSampleCount = #samples,
    courseSampleCount = #course,
    judgedSampleCount = #active,
    courseSpeed = statistics(courseSpeeds),
    courseAngle = statistics(courseAngles),
    judgedSpeed = statistics(U.copy(speeds)),
    judgedAngle = statistics(U.copy(angles)),
    driftEngagementQuality = engagement(active, config) * 100,
    judgedSpeeds = speeds,
    judgedAngles = angles
  }
end

return M

end

__bundled["src.calibration"] = function()
local U = require('src.util')
local M = {}
M.__index = M

local function statistics(values)
  table.sort(values)
  if #values == 0 then return { minimum = 0, average = 0, median = 0, percentile75 = 0, maximum = 0 } end
  local total = 0
  for _, value in ipairs(values) do total = total + value end
  local function percentile(fraction)
    if #values == 1 then return values[1] end
    local position = fraction * (#values - 1)
    local lower, upper = math.floor(position) + 1, math.ceil(position) + 1
    return lower == upper and values[lower] or U.lerp(values[lower], values[upper], position - math.floor(position))
  end
  return {
    minimum = values[1], average = total / #values, median = percentile(0.5),
    percentile75 = percentile(0.75), maximum = values[#values]
  }
end

function M.new()
  return setmetatable({ active = false, attempts = {}, validRuns = {}, recommendation = nil }, M)
end

function M:start()
  self.active, self.attempts, self.validRuns, self.recommendation = true, {}, {}, nil
end

function M:cancel()
  self.active, self.attempts, self.validRuns, self.recommendation = false, {}, {}, nil
end

function M:add(valid, reason, score, analysis)
  local run = {
    attemptNumber = #self.attempts + 1,
    validRunNumber = valid and (#self.validRuns + 1) or 0,
    valid = valid,
    reason = valid and 'Válida' or reason,
    score = score,
    analysis = analysis
  }
  self.attempts[#self.attempts + 1] = run
  if valid then self.validRuns[#self.validRuns + 1] = run end
  if #self.validRuns >= 5 then self.recommendation = self:createRecommendation() end
  return run
end

function M:createRecommendation()
  local best = U.copy(self.validRuns)
  table.sort(best, function(a, b) return a.score.score > b.score.score end)
  while #best > 3 do table.remove(best) end
  local speeds, angles = {}, {}
  for _, run in ipairs(best) do
    for _, value in ipairs(run.analysis.judgedSpeeds) do speeds[#speeds + 1] = value end
    for _, value in ipairs(run.analysis.judgedAngles) do angles[#angles + 1] = value end
  end
  local speedStats, angleStats = statistics(speeds), statistics(angles)
  local targetSpeed = math.ceil(math.max(0, speedStats.average) / 5) * 5
  local targetAngle = math.max(20, U.round(angleStats.average / 5) * 5)
  local minimumAngle = U.clamp(U.round(targetAngle * 0.36 / 5) * 5, 10, targetAngle - 10)
  local styleMinimum = math.max(10, U.round(targetAngle * 0.27 / 5) * 5)
  local styleFull = U.clamp(U.round(targetAngle * 0.55 / 5) * 5, styleMinimum + 5, targetAngle)
  return {
    targetSpeedKmh = targetSpeed,
    targetAngleDeg = targetAngle,
    minimumAngleDeg = minimumAngle,
    styleMinimumDriftAngleDeg = styleMinimum,
    styleFullDriftAngleDeg = styleFull,
    bestRuns = best
  }
end

return M

end

__bundled["src.leaderboard"] = function()
--[[
  Shared, session-only leaderboard broadcast via CSP's ac.OnlineEvent —
  peer-to-peer between clients (relayed through the server's chat-message
  channel under the hood), no dedicated server-side script needed. Every
  client ends up with its own copy, built from everyone's broadcasts,
  including its own (sender.index == 0 means "from me").

  NOT authoritative: a modified client could broadcast a fake score, same
  trust model as the rest of this fork for now. A validated version needs
  an actual server-side script independently re-checking each run — a
  separate, bigger project (see README.md).
]]

local M = {}

-- Keyed by driver name, not car slot: slots get reused when someone leaves
-- and another driver joins, which would otherwise hand the newcomer the
-- previous driver's name and best score.
local entries = {} -- driverName -> { name, score, valid, line, angle, styleSpeed }
local ownBest = nil

local broadcast = ac.OnlineEvent({
  ac.StructItem.key('driftFactoryJudgeApp_runResult'),
  score = ac.StructItem.float(),
  valid = ac.StructItem.boolean(),
  line = ac.StructItem.float(),
  angle = ac.StructItem.float(),
  styleSpeed = ac.StructItem.float(),
}, function(sender, data)
  local carIndex = sender and sender.index or 0
  local name = ac.getDriverName(carIndex) or ('Car ' .. carIndex)
  local existing = entries[name]
  if existing and not (data.valid and (not existing.valid or data.score > existing.score)) then
    return
  end
  entries[name] = {
    name = name,
    score = data.score,
    valid = data.valid,
    line = data.line,
    angle = data.angle,
    styleSpeed = data.styleSpeed,
  }
end)

-- Reports a completed (non-calibration) run's score to everyone else online.
-- A no-op over the network while offline (nothing else is listening), but
-- still updates this client's own leaderboard entry either way.
--
-- `repeatForNewConnections = true` makes CSP remember the last message sent
-- and auto-resend it to anyone who joins later — so the message sent must
-- be this driver's *best* valid run, not just the latest one, or a bad last
-- run is what everyone joining afterwards sees. Runs that don't beat the
-- best aren't sent at all; until a valid run exists, the latest attempt is
-- sent so the driver still shows up.
function M.report(score)
  local payload = {
    score = score.score or 0,
    valid = score.valid or false,
    line = score.line or 0,
    angle = score.angle or 0,
    styleSpeed = score.styleSpeed or 0,
  }
  if payload.valid and (not ownBest or payload.score > ownBest.score) then
    ownBest = payload
  elseif ownBest then
    return
  end
  broadcast(payload, true)
end

-- Best-score-first list of every driver seen this session.
function M.entries()
  local list = {}
  for _, entry in pairs(entries) do list[#list + 1] = entry end
  table.sort(list, function(a, b) return a.score > b.score end)
  return list
end

return M

end

__bundled["src.official_layout"] = function()
--[[
  Official layouts live in the project's public GitHub repo
  (layouts/<track>/<layout>.json), so every player on a server is judged
  against the same admin-published layout — no server config, no app
  update needed to add or change a track. Online sessions use only this,
  never the player's own locally edited layout.
]]

local U = require('src.util')
local Model = require('src.model')
local M = {}

local BASE_URL = 'https://raw.githubusercontent.com/insidedacoolest/drift-jury/master/layouts/'

-- Same folder/file naming as the local layout library (U.sanitizePart), so
-- a layout saved in the editor can be published by copying it as-is.
local function urlPart(value)
  return (U.sanitizePart(value):gsub('[^%w%-%._~]', function(char)
    return string.format('%%%02X', string.byte(char))
  end))
end

function M.url(track, layoutID)
  return BASE_URL .. urlPart(track) .. '/' .. urlPart(layoutID) .. '.json'
end

-- callback(layout) on success, callback(nil, message) on failure.
function M.fetch(track, layoutID, callback)
  web.get(M.url(track, layoutID), function(err, response)
    if (err and err ~= '') or not response then
      callback(nil, 'Sem ligação aos layouts oficiais: ' .. tostring(err))
      return
    end
    if response.status == 404 then
      callback(nil, 'Esta pista ainda não tem layout oficial publicado.')
      return
    end
    if response.status ~= 200 then
      callback(nil, 'Os layouts oficiais responderam com erro ' .. tostring(response.status) .. '.')
      return
    end
    local parsed = U.decodeJson(response.body)
    if not parsed then
      callback(nil, 'O layout oficial desta pista está corrompido.')
      return
    end
    if tostring(parsed.track or ''):lower() ~= tostring(track):lower()
      or tostring(parsed.layout or 'open'):lower() ~= tostring(layoutID):lower() then
      callback(nil, 'O layout oficial publicado não corresponde a esta pista.')
      return
    end
    callback(Model.normalizeLayout(parsed, track, layoutID))
  end)
end

return M

end

__bundled["src.session"] = function()
local U = require('src.util')
local G = require('src.geometry')
local D = require('src.defaults')
local Scoring = require('src.scoring')
local Model = require('src.model')
local Leaderboard = require('src.leaderboard')
local M = {}
M.__index = M

local function worldFromLocal(position, look, localPoint)
  local forward = G.forwardFromLook(look)
  local right = { x = forward.z, y = 0, z = -forward.x }
  return {
    x = position.x + right.x * localPoint.x + forward.x * localPoint.z,
    y = position.y + localPoint.y,
    z = position.z + right.z * localPoint.x + forward.z * localPoint.z
  }
end

local function status(state, message)
  state.message = message
  state.messageAge = 0
end

function M.new(context)
  local session = setmetatable({
    context = context,
    state = 'idle',
    countdownRemaining = 0,
    runElapsed = 0,
    sampleAccumulator = 0,
    samples = {},
    penalties = 0,
    invalid = false,
    invalidReason = '',
    hornWasDown = false,
    previousPosition = nil,
    progressInitialized = false,
    progressSegment = 0,
    lastProgress = nil,
    spinSince = nil,
    lastProgressChanged = 0,
    lastProgressPosition = nil,
    resultAge = 99,
    message = '',
    messageAge = 99,
    deductions = {},
    contact = nil,
    recentSpeeds = {}
  }, M)
  -- Walls and other cars: CSP calls this once as each contact starts.
  if ac.onCarCollision then
    ac.onCarCollision(0, function() session:onCollision() end)
  end
  return session
end

local function contactPenalty(lossKmh)
  local flow = D.flow
  if lossKmh >= flow.contactHardLossKmh then return flow.contactHardPenalty end
  if lossKmh >= flow.contactMediumLossKmh then return flow.contactMediumPenalty end
  return flow.contactLightPenalty
end

function M:onCollision()
  if self.state ~= 'running' then return end
  local now = U.round(self.runElapsed * 1000)
  local car = ac.getCar(0)
  local withCar = car ~= nil and (tonumber(car.collidedWith) or 0) ~= 0
  if self.contact and now - self.contact.lastAt <= D.flow.contactMergeSeconds * 1000 then
    self.contact.lastAt = now
    self.contact.withCar = self.contact.withCar or withCar
    return
  end
  self:closeContact()
  -- Speed just before the hit: the fastest of the last few samples.
  local before = car and tonumber(car.speedKmh) or 0
  for _, speed in ipairs(self.recentSpeeds) do before = math.max(before, speed) end
  self.contact = { startAt = now, lastAt = now, speedBefore = before, minSpeed = before, withCar = withCar }
end

-- Takes points off the run (Drift Masters "deductions"); the HUD flashes it.
function M:deduct(kind, points, label, at)
  self.penalties = self.penalties + points
  self.deductions[#self.deductions + 1] = { kind = kind, points = points }
  self.lastDeductionKind, self.lastDeductionPoints = kind, points
  self.lastDeductionAt = at or U.round(self.runElapsed * 1000)
  status(self, string.format('%s: -%d pontos.', label, points))
end

-- Settles the open contact (if any) into a deduction.
function M:closeContact()
  local contact = self.contact
  if not contact then return end
  self.contact = nil
  local loss = math.max(0, contact.speedBefore - contact.minSpeed)
  self:deduct('contact', contactPenalty(loss), contact.withCar and 'Toque num carro' or 'Toque no muro', contact.startAt)
end

-- Called for every sample while running: tracks how much speed the open
-- contact costs and closes it once the measuring window has passed.
function M:trackContact(sample)
  table.insert(self.recentSpeeds, sample.speedKmh)
  if #self.recentSpeeds > 5 then table.remove(self.recentSpeeds, 1) end
  local contact = self.contact
  if not contact then return end
  contact.minSpeed = math.min(contact.minSpeed, sample.speedKmh)
  if sample.timeMilliseconds - contact.lastAt >= D.flow.contactMeasureSeconds * 1000 then
    self:closeContact()
  end
end

function M:isBusy()
  return self.state == 'countdown' or self.state == 'running'
end

function M:resetProgress()
  self.progressInitialized = false
  self.progressSegment = 0
  self.lastProgress = nil
end

function M:getProgress(position)
  local path, config = self.context.layout.pathWaypoints, self.context.scoring
  if not self.progressInitialized then
    self.lastProgress = G.getProgress(path, position)
    self.progressSegment = self.lastProgress.segmentIndex
    self.progressInitialized = true
    return self.lastProgress
  end
  local candidate = G.getProgress(
    path,
    position,
    math.max(0, self.progressSegment - config.progressSearchBackSegments),
    math.min(math.max(0, #path - 2), self.progressSegment + config.progressSearchForwardSegments))
  if candidate.meters < self.lastProgress.meters then
    local backwards = self.lastProgress.meters - candidate.meters
    if backwards <= config.progressBacktrackToleranceMeters then
      local held = U.copy(self.lastProgress)
      held.distanceToPathMeters = candidate.distanceToPathMeters
      return held
    end
    return self.lastProgress
  end
  self.lastProgress, self.progressSegment = candidate, candidate.segmentIndex
  return candidate
end

function M:sample(nowMilliseconds)
  local car = ac.getCar(0)
  if not car then return nil end
  local position, look, velocity =
    U.fromVec3(car.position), U.fromVec3(car.look), U.fromVec3(car.velocity)
  local progress = self:getProgress(position)
  local signedAngle = G.signedSlipAngle(look, velocity)
  local forward = G.forwardFromLook(look)
  local center = car.aabbCenter and U.fromVec3(car.aabbCenter) or { x = 0, y = 0, z = 0 }
  local size = car.aabbSize and U.fromVec3(car.aabbSize) or { x = 2, y = 1, z = 4.4 }
  local front = worldFromLocal(position, forward, {
    x = center.x, y = center.y, z = center.z + size.z * 0.5
  })
  local rear = worldFromLocal(position, forward, {
    x = center.x, y = center.y, z = center.z - size.z * 0.5
  })
  local leftWheel, rightWheel = car.wheels[2], car.wheels[3]
  local left = leftWheel and U.fromVec3(leftWheel.contactPoint) or rear
  local right = rightWheel and U.fromVec3(rightWheel.contactPoint) or rear
  local steerLock = math.max(1, tonumber(car.steerLock) or 360)
  return {
    timeMilliseconds = nowMilliseconds,
    position = position,
    look = look,
    velocity = velocity,
    steerAngle = U.round(U.clamp(((tonumber(car.steer) or 0) / steerLock + 1) * 127.5, 0, 255)),
    gas = U.round(U.clamp((tonumber(car.gas) or 0) * 255, 0, 255)),
    signedAngleDeg = signedAngle,
    angleDeg = math.abs(signedAngle),
    speedKmh = math.sqrt(velocity.x * velocity.x + velocity.y * velocity.y + velocity.z * velocity.z) * 3.6,
    progress = progress,
    frontBumper = front,
    rearBumper = rear,
    rearWheelLeft = left,
    rearWheelRight = right,
    rearWheelLeftExact = leftWheel ~= nil,
    rearWheelRightExact = rightWheel ~= nil,
    exactWheelCoverage = (leftWheel and 0.5 or 0) + (rightWheel and 0.5 or 0),
    wheelsOutside = tonumber(car.wheelsOutside) or 0
  }
end

-- Unit direction of the route segment the car is on, flattened to the ground.
local function courseDirection(path, segmentIndex)
  local a, b = path[segmentIndex + 1], path[segmentIndex + 2]
  if not a or not b then return nil end
  local dx, dz = b.x - a.x, b.z - a.z
  local length = math.sqrt(dx * dx + dz * dz)
  if length < 0.01 then return nil end
  return dx / length, dz / length
end

local function routeLength(path)
  local total = 0
  for index = 2, #path do total = total + G.distance3(path[index - 1], path[index]) end
  return total
end

-- True once `condition` has held continuously for `graceSeconds`;
-- timers are kept per rule in self.ruleSince.
function M:sustained(rule, condition, now, graceSeconds)
  if not condition then
    self.ruleSince[rule] = nil
    self.ruleFired[rule] = nil
    return false
  end
  self.ruleSince[rule] = self.ruleSince[rule] or now
  return now - self.ruleSince[rule] >= graceSeconds * 1000
end

-- Like sustained(), but true only once per episode: the condition has to
-- clear before the same rule can fire again (one deduction per mistake).
function M:episode(rule, condition, now, graceSeconds)
  if not self:sustained(rule, condition, now, graceSeconds) or self.ruleFired[rule] then return false end
  self.ruleFired[rule] = true
  return true
end

function M:beginCountdown()
  local context, pose = self.context, self.context.layout.leadStart
  if not pose then return end
  -- Auto-align (teleport to the start line) needs physics write access,
  -- which CSP itself withholds once connected to a multiplayer server —
  -- online, the driver lines up manually during the countdown instead.
  if physics.allowed() then
    physics.disableCarCollisions(0, true, false)
    local direction = pose.direction
    physics.setCarPosition(0, U.toVec3(pose.position), vec3(
      -(direction.x or 0), -(direction.y or 0), -(direction.z or 1)))
    physics.setCarVelocity(0, vec3())
  end
  self.state = 'countdown'
  self.countdownRemaining = D.flow.countdownSeconds
  self.samples, self.penalties, self.invalid, self.invalidReason = {}, 0, false, ''
  self.deductions, self.contact, self.recentSpeeds, self.lastDeductionAt = {}, nil, {}, nil
  self.ruleFired = {}
  self.previousPosition, self.spinSince = nil, nil
  self.ruleSince, self.driftEngaged = {}, false
  self:resetProgress()
  status(self, context.calibration.active and 'Contagem decrescente de calibração iniciada.' or 'Contagem decrescente iniciada.')
end

function M:beginRun()
  self.state = 'running'
  self.runElapsed, self.sampleAccumulator = 0, 0
  self.ruleSince, self.ruleFired, self.driftEngaged, self.launched = {}, {}, false, false
  self.courseLength = routeLength(self.context.layout.pathWaypoints)
  self:resetProgress()
  local first = self:sample(0)
  self.previousPosition = first and first.position or nil
  self.lastProgress = first and first.progress or nil
  self.lastProgressChanged = 0
  self.lastProgressPosition = first and first.position or nil
  status(self, 'Vai!')
end

function M:markInvalid(reason)
  if self.invalid then return end
  self.invalid, self.invalidReason = true, reason
end

function M:checkInvalid(sample)
  if sample.angleDeg < D.flow.spinAngleDeg then
    self.spinSince = nil
  else
    self.spinSince = self.spinSince or sample.timeMilliseconds
    if sample.timeMilliseconds - self.spinSince >= D.flow.spinGraceSeconds * 1000 then
      self:markInvalid('Trompo')
    end
  end
  if not self.lastProgressPosition then
    self.lastProgressChanged = sample.timeMilliseconds
    self.lastProgressPosition = sample.position
    self.lastProgress = sample.progress
  else
    local courseDelta = sample.progress.meters - self.lastProgress.meters
    local worldDelta = G.distance3(sample.position, self.lastProgressPosition)
    if courseDelta >= D.flow.noProgressMeters or worldDelta >= D.flow.noProgressMeters then
      self.lastProgressChanged = sample.timeMilliseconds
      self.lastProgressPosition = sample.position
      self.lastProgress = sample.progress
    end
    if sample.timeMilliseconds - self.lastProgressChanged >= D.flow.noProgressSeconds * 1000 then
      self:markInvalid('Sem progresso no percurso')
    end
  end

  local now, flow, scoring = sample.timeMilliseconds, D.flow, self.context.scoring

  -- Driving the wrong way: moving back along the route.
  local dirX, dirZ = courseDirection(self.context.layout.pathWaypoints, sample.progress.segmentIndex or 0)
  local horizontalSpeed = math.sqrt(sample.velocity.x * sample.velocity.x + sample.velocity.z * sample.velocity.z)
  local backwards = dirX ~= nil and sample.speedKmh >= flow.wrongWayMinSpeedKmh and horizontalSpeed > 0
    and (sample.velocity.x * dirX + sample.velocity.z * dirZ) / horizontalSpeed < -0.2
  if self:sustained('wrongWay', backwards, now, flow.wrongWayGraceSeconds) then
    self:markInvalid('Sentido contrário')
  end

  -- Straightening up: only once the drift has started, and not in the last
  -- meters before the finish where drivers may straighten to cross it.
  if sample.angleDeg >= scoring.minimumAngleDeg then self.driftEngaged = true end
  local remaining = (self.courseLength or 0) - sample.progress.meters
  -- A stopped car has no slip angle either; that case is reported as a stop.
  local straight = self.driftEngaged and sample.angleDeg < flow.straightenAngleDeg
    and sample.speedKmh >= flow.stopSpeedKmh and remaining > scoring.finishExclusionMeters
  -- A short straightening is a correction (deduction); staying straight is
  -- "stop drifting" (incomplete).
  if self:episode('straighten', straight, now, flow.straightenGraceSeconds) then
    self:deduct('straighten', flow.straightenDeduction, 'Endireitou (correção)', now)
  end
  if self:sustained('stopDrifting', straight, now, flow.stopDriftingSeconds) then
    self:markInvalid('Parou de derrapar')
  end

  -- Track limits: three wheels off is incomplete, one or two a deduction.
  local wheelsOff = sample.wheelsOutside or 0
  if self:sustained('offTrack', wheelsOff >= flow.offTrackWheels, now, flow.offTrackGraceSeconds) then
    self:markInvalid('Três rodas fora da pista')
  end
  if self:episode('tireOff', wheelsOff >= flow.tireOffWheels, now, flow.offTrackGraceSeconds) then
    self:deduct('tireOff', flow.tireOffDeduction, 'Roda fora da pista', now)
  end

  -- Stopping: only after the launch, so a slow reaction at "Vai!" isn't a stop
  -- (never launching at all is caught by the no-progress rule above).
  if sample.speedKmh >= flow.launchedSpeedKmh then self.launched = true end
  if self:sustained('stop', self.launched and sample.speedKmh < flow.stopSpeedKmh, now, flow.stopGraceSeconds) then
    self:markInvalid('Parou o carro')
  end
end

function M:finish(reason)
  local context = self.context
  self:closeContact()
  local score = Scoring.scoreLead(
    self.samples, context.layout, context.scoring, self.penalties, self.invalid, self.invalidReason)
  score.reason = score.valid and 'Válida' or (self.invalidReason ~= '' and self.invalidReason or reason)
  score.calibration = context.calibration.active
  -- Deductions only matter for a completed run.
  score.deductionCount = score.valid and #self.deductions or 0
  local contacts = 0
  for _, deduction in ipairs(self.deductions) do
    if deduction.kind == 'contact' then contacts = contacts + 1 end
  end
  score.contacts = score.valid and contacts or 0
  context.lastResult = score
  self.resultAge = 0
  if physics.allowed() then physics.disableCarCollisions(0, false, false) end
  self.state = 'result'
  if context.calibration.active then
    local analysis = Scoring.analyzeRun(self.samples, context.layout, context.scoring)
    local run = context.calibration:add(score.valid, score.reason, score, analysis)
    status(self, run.valid
      and string.format('Run de calibração %d/5 válida: %.1f pontos.', #context.calibration.validRuns, score.score)
      or string.format('Tentativa de calibração inválida: %s.', run.reason))
  else
    Leaderboard.report(score)
    local ok, recordOrError = context.storage:addResult(context.results, score)
    if not ok then
      status(self, 'Resultado guardado em memória, mas falhou ao gravar: ' .. tostring(recordOrError))
    else
      context.lastResult = recordOrError
      status(self, recordOrError.personalBest
        and string.format('Novo PB: %.1f pontos!', score.score)
        or (score.valid and string.format('Pontuação: %.1f pontos.', score.score)
          or 'Run inválida: ' .. score.reason))
    end
  end
end

function M:cancel(message)
  if not self:isBusy() then return end
  if physics.allowed() then physics.disableCarCollisions(0, false, false) end
  self.state = 'idle'
  self.samples = {}
  status(self, message or 'Run cancelada.')
end

function M:update(dt)
  self.messageAge = self.messageAge + dt
  self.resultAge = self.resultAge + dt
  local context = self.context
  local sim, car = ac.getSim(), ac.getCar(0)
  if not sim or not car then return end
  local hornDown = car.hornActive == true
  local hornEdge = hornDown and not self.hornWasDown
  self.hornWasDown = hornDown

  -- Replay genuinely can't run a live judged session (no live telemetry to
  -- judge). Online multiplayer used to be blocked here too, in the
  -- original DriftJudging SP — see CREDITS.md for why this fork keeps it
  -- working online instead.
  if sim.isReplayActive then
    if self:isBusy() then self:cancel('Run cancelada: isto é um replay.') end
    return
  end

  if self.state == 'result' and self.resultAge > 4 then self.state = 'idle' end
  if self.state == 'idle' or self.state == 'result' then
    if hornEdge and Model.isReady(context.layout)
      and context.calibration.recommendation == nil
      and G.insideCircle(U.fromVec3(car.position), context.layout.leadStart.position,
        context.layout.leadStart.radiusMeters) then
      self:beginCountdown()
    end
    return
  end

  if self.state == 'countdown' then
    self.countdownRemaining = self.countdownRemaining - dt
    -- Moving off before the countdown ends voids the run outright.
    local speed = tonumber(car.speedKmh) or 0
    if speed > D.flow.jumpStartSpeedKmh then
      self:markInvalid('Partida antecipada')
      self:finish('Partida antecipada')
      return
    end
    if self.countdownRemaining <= 0 then self:beginRun() end
    return
  end

  if self.state == 'running' then
    self.runElapsed = self.runElapsed + dt
    self.sampleAccumulator = self.sampleAccumulator + dt
    while self.sampleAccumulator >= 0.05 do
      self.sampleAccumulator = self.sampleAccumulator - 0.05
      local sample = self:sample(U.round(self.runElapsed * 1000))
      if sample then
        self.samples[#self.samples + 1] = sample
        self:trackContact(sample)
        self:checkInvalid(sample)
        if self.invalid then self:finish(self.invalidReason) return end
        if self.previousPosition and G.crossedGate(
          self.previousPosition, sample.position, context.layout.finishGate) then
          self:finish('Terminada')
          return
        end
        self.previousPosition = sample.position
      end
    end
    if self.runElapsed >= D.flow.maxRunSeconds then
      self:markInvalid('Tempo limite excedido')
      self:finish('Tempo limite excedido')
    end
  end
end

return M

end

__bundled["src.editor"] = function()
local U = require('src.util')
local G = require('src.geometry')
local D = require('src.defaults')
local M = {}
M.__index = M

local function cloneCarPose()
  local car = ac.getCar(0)
  if not car then return nil end
  return U.fromVec3(car.position), G.forwardFromLook(U.fromVec3(car.look))
end

local function distanceSquared(a, b)
  local x, z = a.x - b.x, a.z - b.z
  return x * x + z * z
end

local function pointSegmentDistanceSquared(point, a, b)
  local x, z = b.x - a.x, b.z - a.z
  local length = x * x + z * z
  if length < 0.0001 then return distanceSquared(point, a) end
  local t = U.clamp(((point.x - a.x) * x + (point.z - a.z) * z) / length, 0, 1)
  local dx, dz = point.x - (a.x + x * t), point.z - (a.z + z * t)
  return dx * dx + dz * dz
end

function M.new(context)
  return setmetatable({
    context = context,
    mode = 'none',
    recording = false,
    outerDraft = {},
    undo = {},
    dragging = nil,
    hiddenOuterZones = {},
    hiddenInnerClips = {},
    previousLeft = false,
    previousRight = false,
    routeSmoothRadius = 15,
    startRadius = D.editor.startRadiusMeters,
    finishWidth = D.editor.finishWidthMeters,
    clipRadius = D.editor.clipRadiusMeters,
    debug = false
  }, M)
end

function M:isOuterZoneVisible(index)
  return self.hiddenOuterZones[index] ~= true
end

function M:setOuterZoneVisible(index, visible)
  if visible then
    self.hiddenOuterZones[index] = nil
  else
    self.hiddenOuterZones[index] = true
  end
  if not visible
    and self.dragging
    and self.dragging.kind == 'outer'
    and self.dragging.zone == index then
    self.dragging = nil
  end
end

function M:isInnerClipVisible(index)
  return self.hiddenInnerClips[index] ~= true
end

function M:setInnerClipVisible(index, visible)
  if visible then
    self.hiddenInnerClips[index] = nil
  else
    self.hiddenInnerClips[index] = true
  end
end

function M:pushUndo()
  self.undo[#self.undo + 1] = U.copy(self.context.layout)
  while #self.undo > 25 do table.remove(self.undo, 1) end
end

function M:changed(message)
  self.context.dirty = true
  self.context.status = message
end

function M:undoLast()
  if #self.undo == 0 then return end
  self.context.layout = table.remove(self.undo)
  self.context:refreshScoring()
  self:changed('Desfeita a última edição do layout.')
end

function M:setMode(mode)
  self.mode = self.mode == mode and 'none' or mode
  self.dragging = nil
end

function M:captureLeadStart()
  local position, direction = cloneCarPose()
  if not position then return end
  self:pushUndo()
  self.context.layout.leadStart = {
    position = position, direction = direction, radiusMeters = self.startRadius
  }
  self:changed('Partida capturada.')
end

function M:captureFinish()
  local position, direction = cloneCarPose()
  if not position then return end
  self:pushUndo()
  self.context.layout.finishGate = {
    center = position, direction = direction, widthMeters = self.finishWidth
  }
  self:changed('Gate de chegada capturado.')
end

function M:addRoutePoint(position)
  self.context.layout.pathWaypoints[#self.context.layout.pathWaypoints + 1] = U.copy(position)
end

function M:toggleRecording()
  self.recording = not self.recording
  if self.recording then
    self:pushUndo()
    self.mode = 'none'
    local position = cloneCarPose()
    if position then self:addRoutePoint(position) end
    self:changed('Gravação da rota iniciada.')
  else
    self:changed('Gravação da rota parada.')
  end
end

function M:clearRoute()
  if #self.context.layout.pathWaypoints == 0 then return end
  self:pushUndo()
  self.context.layout.pathWaypoints = {}
  self:changed('Rota limpa.')
end

function M:finishOuter()
  if #self.outerDraft < 3 then
    self.context.status = 'Uma zona exterior precisa de pelo menos três pontos.'
    return
  end
  self:pushUndo()
  self.context.layout.outerZones[#self.context.layout.outerZones + 1] = {
    name = 'Exterior ' .. (#self.context.layout.outerZones + 1),
    points = U.copy(self.outerDraft)
  }
  self.outerDraft = {}
  self:changed('Zona exterior adicionada.')
end

function M:cancelOuter()
  self.outerDraft = {}
  self.context.status = 'Rascunho da zona exterior cancelado.'
end

function M:updateRecording()
  if not self.recording then return end
  local car = ac.getCar(0)
  if not car then return end
  local position = U.fromVec3(car.position)
  local route = self.context.layout.pathWaypoints
  if #route == 0 or G.distance2(route[#route], position) >= D.editor.pathRecordingSpacingMeters then
    self:addRoutePoint(position)
    self.context.dirty = true
  end
end

function M:rayHit()
  if not render.createMouseRay then return nil end
  local ray = render.createMouseRay()
  if not ray then return nil end
  local distance = ray:track()
  if not distance or distance < 0 then return nil end
  return U.fromVec3(ray.pos + ray.dir * distance)
end

function M:nearestRoute(point, radius)
  local best, bestDistance = nil, radius * radius
  for index, routePoint in ipairs(self.context.layout.pathWaypoints) do
    local distance = distanceSquared(point, routePoint)
    if distance <= bestDistance then best, bestDistance = index, distance end
  end
  return best
end

function M:nearestRouteSegment(point, radius)
  local route = self.context.layout.pathWaypoints
  local best, bestDistance = nil, radius * radius
  for index = 1, #route - 1 do
    local distance = pointSegmentDistanceSquared(point, route[index], route[index + 1])
    if distance <= bestDistance then best, bestDistance = index, distance end
  end
  return best
end

function M:nearestOuter(point, radius)
  local best, bestDistance = nil, radius * radius
  for index, draftPoint in ipairs(self.outerDraft) do
    local distance = distanceSquared(point, draftPoint)
    if distance <= bestDistance then
      best, bestDistance = { draft = true, index = index }, distance
    end
  end
  for zoneIndex, zone in ipairs(self.context.layout.outerZones) do
    if self:isOuterZoneVisible(zoneIndex) then
      for index, zonePoint in ipairs(zone.points) do
        local distance = distanceSquared(point, zonePoint)
        if distance <= bestDistance then
          best, bestDistance = { zone = zoneIndex, index = index }, distance
        end
      end
    end
  end
  return best
end

function M:nearestOuterEdge(point, radius)
  local best, bestDistance = nil, radius * radius
  for zoneIndex, zone in ipairs(self.context.layout.outerZones) do
    if self:isOuterZoneVisible(zoneIndex) then
      for index = 1, #zone.points do
        local distance = pointSegmentDistanceSquared(point, zone.points[index], zone.points[index % #zone.points + 1])
        if distance <= bestDistance then
          best, bestDistance = { zone = zoneIndex, index = index }, distance
        end
      end
    end
  end
  return best
end

function M:nearestClip(point, radius)
  local best, bestDistance = nil, radius * radius
  for index, clip in ipairs(self.context.layout.innerClips) do
    if self:isInnerClipVisible(index) then
      local distance = distanceSquared(point, clip.position)
      if distance <= bestDistance then best, bestDistance = index, distance end
    end
  end
  return best
end

function M:applyRouteDrag(hit)
  local route = self.context.layout.pathWaypoints
  local drag = self.dragging
  if not drag or drag.kind ~= 'route' then return end
  if drag.smooth ~= true then
    route[drag.index] = U.copy(hit)
    return
  end

  local original = drag.originalRoute
  if not original or not original[drag.index] then return end
  local cumulative = { 0 }
  for index = 2, #original do
    cumulative[index] = cumulative[index - 1] + G.distance2(original[index - 1], original[index])
  end

  local source = original[drag.index]
  local delta = {
    x = hit.x - source.x,
    y = (hit.y or 0) - (source.y or 0),
    z = hit.z - source.z
  }
  local radius = U.clamp(tonumber(drag.smoothRadius) or self.routeSmoothRadius, 5, 30)
  local selectedDistance = cumulative[drag.index] or 0
  for index, point in ipairs(original) do
    local routeDistance = math.abs((cumulative[index] or 0) - selectedDistance)
    if routeDistance <= radius then
      local weight = 0.5 * (1 + math.cos(math.pi * routeDistance / radius))
      route[index] = {
        x = point.x + delta.x * weight,
        y = (point.y or 0) + delta.y * weight,
        z = point.z + delta.z * weight
      }
    else
      route[index] = U.copy(point)
    end
  end
  route[drag.index] = U.copy(hit)
end

function M:uiCapturesMouse()
  local state = ac.getUI and ac.getUI() or nil
  return state and state.wantCaptureMouse == true
end

function M:update3D()
  if self.context.session:isBusy() or self.context.calibration.active then
    self.recording = false
    self.dragging = nil
    return
  end
  self:updateRecording()
  if self.mode == 'none' then
    self.dragging = nil
    return
  end
  local hit = self:rayHit()
  if not hit then return end
  local leftButton = ui.MouseButton and ui.MouseButton.Left or 0
  local rightButton = ui.MouseButton and ui.MouseButton.Right or 1
  local left = ui.mouseDown and ui.mouseDown(leftButton) or false
  local right = ui.mouseDown and ui.mouseDown(rightButton) or false
  local leftPressed, leftReleased = left and not self.previousLeft, not left and self.previousLeft
  local rightPressed = right and not self.previousRight
  local ctrl = ui.keyboardButtonDown and ui.KeyIndex
    and ui.keyboardButtonDown(ui.KeyIndex.Control)
  local shift = ui.keyboardButtonDown and ui.KeyIndex and ui.KeyIndex.Shift
    and ui.keyboardButtonDown(ui.KeyIndex.Shift)
  local captured = self:uiCapturesMouse()

  if self.dragging and left then
    if self.dragging.kind == 'route' then
      self:applyRouteDrag(hit)
    elseif self.dragging.kind == 'outerDraft' then
      self.outerDraft[self.dragging.index] = U.copy(hit)
    elseif self.dragging.kind == 'outer' then
      self.context.layout.outerZones[self.dragging.zone].points[self.dragging.index] = U.copy(hit)
    end
    self.context.dirty = true
  end
  if self.dragging and leftReleased then
    self.dragging = nil
    self:changed('Ponto movido.')
  end

  if not captured and leftPressed and not self.dragging then
    if self.mode == 'route' then
      if ctrl then
        local segment = self:nearestRouteSegment(hit, 2)
        if segment then
          self:pushUndo()
          table.insert(self.context.layout.pathWaypoints, segment + 1, U.copy(hit))
          self:changed('Ponto de rota inserido.')
        end
      else
        local index = self:nearestRoute(hit, 0.8)
        if index then
          self:pushUndo()
          self.dragging = {
            kind = 'route',
            index = index,
            smooth = shift == true,
            smoothRadius = self.routeSmoothRadius,
            originalRoute = U.copy(self.context.layout.pathWaypoints)
          }
        end
      end
    elseif self.mode == 'outer' then
      if ctrl then
        local edge = self:nearestOuterEdge(hit, 2)
        self:pushUndo()
        if edge then
          table.insert(self.context.layout.outerZones[edge.zone].points, edge.index + 1, U.copy(hit))
          self:changed('Ponto da zona exterior inserido.')
        else
          self.outerDraft[#self.outerDraft + 1] = U.copy(hit)
          self.context.status = 'Ponto de rascunho exterior adicionado.'
        end
      else
        local target = self:nearestOuter(hit, 0.8)
        if target then
          self:pushUndo()
          self.dragging = target.draft
            and { kind = 'outerDraft', index = target.index }
            or { kind = 'outer', zone = target.zone, index = target.index }
        end
      end
    elseif self.mode == 'clip' and ctrl then
      self:pushUndo()
      self.context.layout.innerClips[#self.context.layout.innerClips + 1] = {
        name = 'Clip ' .. (#self.context.layout.innerClips + 1),
        position = U.copy(hit),
        radiusMeters = self.clipRadius
      }
      self:changed('Clip interior adicionado.')
    end
  end

  if not captured and rightPressed then
    if self.mode == 'route' then
      local index = self:nearestRoute(hit, 0.8)
      if index and #self.context.layout.pathWaypoints > 2 then
        self:pushUndo()
        table.remove(self.context.layout.pathWaypoints, index)
        self:changed('Ponto de rota removido.')
      end
    elseif self.mode == 'outer' then
      local target = self:nearestOuter(hit, 0.8)
      if target then
        if target.draft then
          table.remove(self.outerDraft, target.index)
          self.context.status = 'Ponto de rascunho removido.'
        else
          local points = self.context.layout.outerZones[target.zone].points
          if #points > 3 then
            self:pushUndo()
            table.remove(points, target.index)
            self:changed('Ponto da zona exterior removido.')
          end
        end
      end
    elseif self.mode == 'clip' then
      local index = self:nearestClip(hit, 1)
      if index then
        self:pushUndo()
        table.remove(self.context.layout.innerClips, index)
        self:changed('Clip interior removido.')
      end
    end
  end

  self.previousLeft, self.previousRight = left, right
end

return M

end

__bundled["src.draw"] = function()
local U = require('src.util')
local G = require('src.geometry')
local M = {}

local colors = {
  route = rgbm(0.85, 0.9, 1, 1),
  corridor = rgbm(0.25, 0.75, 1, 0.9),
  start = rgbm(0.2, 1, 0.25, 1),
  finish = rgbm(1, 0.9, 0.2, 1),
  outer = rgbm(1, 0.42, 0.05, 1),
  draft = rgbm(1, 0.1, 1, 1),
  clip = rgbm(0.2, 1, 1, 1)
}

-- Palette pulled from driftfactory.pt, used for the score HUD specifically
-- (not the 3D editor markers above, which keep their own scheme).
local BRAND = {
  panelBg = rgbm(11 / 255, 12 / 255, 15 / 255, 0.92),
  accent = rgbm(212 / 255, 255 / 255, 63 / 255, 1), -- lime
  accent2 = rgbm(255 / 255, 62 / 255, 200 / 255, 1), -- magenta, invalid/attention
  text = rgbm(243 / 255, 244 / 255, 239 / 255, 1), -- cream
  muted = rgbm(154 / 255, 160 / 255, 172 / 255, 1),
}

local hudWindowWidth = 300
local hudWindowTopPadding = 26
local hudWindowBottomPadding = 6

local function elevate(point, amount)
  return vec3(point.x, point.y + (amount or 0.08), point.z)
end

local function line(a, b, color, height)
  render.debugLine(elevate(a, height), elevate(b, height), color)
end

local function circle(point, radius, color)
  local segments = math.max(20, math.min(48, math.ceil(radius * 12)))
  local previous = { x = point.x + radius, y = point.y, z = point.z }
  for index = 1, segments do
    local angle = index / segments * math.pi * 2
    local current = {
      x = point.x + math.cos(angle) * radius,
      y = point.y,
      z = point.z + math.sin(angle) * radius
    }
    line(previous, current, color)
    previous = current
  end
end

local function label(point, text, color)
  if render.debugText then
    render.debugText(elevate(point, 0.35), text, color, 0.8, render.FontAlign.Left)
  end
end

local function drawRoute(layout)
  local route = layout.pathWaypoints
  for index = 2, #route do line(route[index - 1], route[index], colors.route) end
  for index, point in ipairs(route) do
    circle(point, 0.3, colors.route)
    if index == 1 or (index - 1) % 10 == 0 then label(point, 'P' .. index, colors.route) end
  end
  if #route >= 2 then
    local left = G.createOffsetPath(route, layout.pathCorridorHalfWidthMeters)
    local right = G.createOffsetPath(route, -layout.pathCorridorHalfWidthMeters)
    for index = 2, #left do
      line(left[index - 1], left[index], colors.corridor)
      line(right[index - 1], right[index], colors.corridor)
    end
  end
end

local function drawFinish(gate)
  local direction = G.forwardFromLook(gate.direction)
  local lateral = { x = -direction.z, y = 0, z = direction.x }
  local half = gate.widthMeters * 0.5
  local a = { x = gate.center.x - lateral.x * half, y = gate.center.y, z = gate.center.z - lateral.z * half }
  local b = { x = gate.center.x + lateral.x * half, y = gate.center.y, z = gate.center.z + lateral.z * half }
  line(a, b, colors.finish, 0.15)
  line(gate.center, {
    x = gate.center.x + direction.x * 4,
    y = gate.center.y,
    z = gate.center.z + direction.z * 4
  }, colors.finish, 0.15)
  label(gate.center, 'CHEGADA', colors.finish)
end

function M.layout(context)
  local editor, layout = context.editor, context.layout
  -- Start and finish are always drawn: every player needs them to find
  -- where a run begins and ends, including online players who never see
  -- the editor's debug toggle.
  if layout.leadStart then
    circle(layout.leadStart.position, layout.leadStart.radiusMeters, colors.start)
    label(layout.leadStart.position, 'PARTIDA', colors.start)
  end
  if layout.finishGate then drawFinish(layout.finishGate) end
  -- Zones and clips: in the editor's debug mode, or when the player turns
  -- on "Mostrar zonas e clips". The route and its nodes are editor-only.
  if not (editor.debug or context.showCourse) then return end
  if editor.debug then drawRoute(layout) end
  for zoneIndex, zone in ipairs(layout.outerZones) do
    if not editor.debug or editor:isOuterZoneVisible(zoneIndex) then
      for index, point in ipairs(zone.points) do
        line(point, zone.points[index % #zone.points + 1], colors.outer, 0.12)
        circle(point, 0.3, colors.outer)
        if index == 1 then label(point, 'EXTERIOR ' .. zoneIndex, colors.outer) end
      end
    end
  end
  for index, clip in ipairs(layout.innerClips) do
    if not editor.debug or editor:isInnerClipVisible(index) then
      circle(clip.position, clip.radiusMeters, colors.clip)
      label(clip.position, 'CLIP ' .. index, colors.clip)
      -- (kept as "CLIP" untranslated — common drift-scene loanword)
    end
  end
  if not editor.debug then return end
  for index, point in ipairs(editor.outerDraft) do
    circle(point, 0.35, colors.draft)
    if index > 1 then line(editor.outerDraft[index - 1], point, colors.draft, 0.15) end
  end
  if editor.mode ~= 'none' then
    local hit = editor:rayHit()
    if hit then circle(hit, editor.mode == 'clip' and editor.clipRadius or 0.55, colors.draft) end
  end
end

local function fill(p1, p2, color, rounding)
  ui.drawRectFilled(p1, p2, color, rounding or 5)
end

-- Brand typefaces (driftfactory.pt), shipped as TTFs in the app's fonts/
-- folder under the SIL Open Font License: Saira for titles and big numbers,
-- JetBrains Mono for small readouts so digits keep a fixed width. Built
-- lazily; if CSP can't build them, everything falls back to its default font.
local FONTS_DIR = './fonts'
local brandFonts = nil

-- The online script has no app folder: it downloads the fonts and points
-- here at the folder CSP unpacked them into.
function M.setFontsDir(dir)
  FONTS_DIR = dir
  brandFonts = nil
end

local function fontFor(role)
  if brandFonts == nil then
    brandFonts = false
    if ui.DWriteFont and ui.pushDWriteFont then
      local ok, result = pcall(function()
        local weight = ui.DWriteFont.Weight
        return {
          title = ui.DWriteFont('Saira', FONTS_DIR):weight(weight.SemiBold),
          number = ui.DWriteFont('Saira', FONTS_DIR):weight(weight.Bold),
          mono = ui.DWriteFont('JetBrains Mono', FONTS_DIR):weight(weight.Medium),
          monoBold = ui.DWriteFont('JetBrains Mono', FONTS_DIR):weight(weight.Bold),
        }
      end)
      if ok then brandFonts = result end
    end
  end
  return brandFonts and role and brandFonts[role] or nil
end

local function withFont(role, drawFn)
  local font = fontFor(role)
  if font then ui.pushDWriteFont(font) end
  drawFn()
  if font then ui.popDWriteFont() end
end

local function text(value, size, position, color, role)
  if ui.dwriteDrawText then
    withFont(role, function() ui.dwriteDrawText(value, size, position, color) end)
  else
    ui.setCursor(position)
    ui.textColored(value, color)
  end
end

-- Text placed inside a box with real alignment, so numbers and labels land
-- where the layout says instead of depending on font metrics. Falls back to
-- top-left placement on CSP builds without the clipped DWrite call.
local function textIn(value, size, boxMin, boxMax, hAlign, vAlign, color, role)
  if ui.dwriteDrawTextClipped and ui.Alignment then
    withFont(role, function()
      ui.dwriteDrawTextClipped(value, size, boxMin, boxMax,
        ui.Alignment[hAlign or 'Start'], ui.Alignment[vAlign or 'Center'], false, color)
    end)
  else
    text(value, size, boxMin, color, role)
  end
end

-- A slanted "speed stripe" instead of a plain vertical accent bar — the
-- recurring livery-style signature element that shows up in every HUD state.
local function accentStripe(p1, p2, color)
  ui.drawQuadFilled(
    vec2(p1.x, p1.y), vec2(p1.x + 16, p1.y),
    vec2(p1.x + 6, p2.y), vec2(p1.x, p2.y), color)
end

-- Small cut-corner wedge at the panel's top-right, like a livery badge.
local function cornerWedge(topRight, size, color)
  ui.drawTriangleFilled(
    vec2(topRight.x - size, topRight.y), topRight, vec2(topRight.x, topRight.y + size), color)
end

local function withAlpha(color, alpha)
  return rgbm(color.r, color.g, color.b, color.mult * alpha)
end

-- Expanding, fading ring — used to give the countdown a "pulse" every second.
-- `grow` bounds the expansion so the ring never leaves the panel.
local function pulseRing(center, baseRadius, grow, phase, color)
  ui.drawCircle(center, baseRadius + phase * grow, withAlpha(color, 1 - phase), 40, 2.5)
end

local function arc(center, radius, angleFrom, angleTo, color, thickness)
  local segments = 28
  local previous = nil
  for i = 0, segments do
    local t = i / segments
    local angle = angleFrom + (angleTo - angleFrom) * t
    local point = vec2(center.x + math.cos(angle) * radius, center.y + math.sin(angle) * radius)
    if previous then ui.drawLine(previous, point, color, thickness) end
    previous = point
  end
end

-- Speedometer-style gauge: 240 degree sweep opening at the bottom, apex at
-- the top. Color runs from the lime accent toward magenta as the value
-- approaches/exceeds the target, so the driver reads "getting hot" at a
-- glance instead of having to read the number.
local function angleGauge(center, radius, valueDeg, maxDeg, targetDeg, trackColor)
  local angleFrom, angleTo = math.rad(150), math.rad(390)
  arc(center, radius, angleFrom, angleTo, trackColor, 5)
  local normalized = U.clamp(valueDeg / maxDeg, 0, 1)
  local heat = U.clamp(valueDeg / math.max(1, targetDeg), 0, 1.4) / 1.4
  local needleColor = rgbm(
    BRAND.accent.r + (BRAND.accent2.r - BRAND.accent.r) * heat,
    BRAND.accent.g + (BRAND.accent2.g - BRAND.accent.g) * heat,
    BRAND.accent.b + (BRAND.accent2.b - BRAND.accent.b) * heat, 1)
  arc(center, radius, angleFrom, angleFrom + (angleTo - angleFrom) * normalized, needleColor, 5)
  local tip = vec2(center.x + math.cos(angleFrom + (angleTo - angleFrom) * normalized) * radius,
    center.y + math.sin(angleFrom + (angleTo - angleFrom) * normalized) * radius)
  ui.drawCircleFilled(tip, 5, needleColor)
end

-- A fan of "speed lines" shooting out to the right of the score, fading out —
-- the flourish that fires once on a new personal best. The inner radius
-- keeps the lines clear of the number itself.
local function speedBurst(center, phase, color)
  local count = 5
  local innerRadius, outerRadius = 40 + phase * 6, 50 + phase * 14
  local alpha = 1 - phase
  for i = 1, count do
    local angle = -0.5 + (i - 1) / (count - 1) * 1.0
    local dir = vec2(math.cos(angle), math.sin(angle))
    local a = center + dir * innerRadius
    local b = center + dir * outerRadius
    ui.drawLine(a, b, withAlpha(color, alpha * 0.8), 3)
  end
end

-- Panel heights per state. The HUD only carries what a driver reads at a
-- glance: the count, angle and speed while driving, and the score (or why
-- the run was voided) at the end.
local hudHeights = { countdown = 76, running = 72, result = 100, idle = 106 }

function M.hudSize(context)
  local state = context.session.state
  return hudWindowWidth, hudHeights[state] or hudHeights.countdown
end

function M.hudWindowSize(context)
  local panelHeight = context and select(2, M.hudSize(context)) or hudHeights.result
  if context and not context.session:isBusy() and context.session.resultAge >= 4 then
    panelHeight = hudHeights.idle
  end
  return hudWindowWidth, panelHeight + hudWindowTopPadding + hudWindowBottomPadding
end

local function panel(p1, p2, accent)
  fill(p1, p2, BRAND.panelBg, 4)
  accentStripe(p1, vec2(p1.x, p2.y), accent)
  cornerWedge(vec2(p2.x, p1.y), 14, accent)
end

-- Between runs: what to do next (drive to the start, or honk once inside
-- it) and the rules that void a run, so a first-time player needs no menu.
local function guide(context, p1)
  local p2 = p1 + vec2(hudWindowWidth, hudHeights.idle)
  local layout = context.layout
  local start = layout.leadStart
  local ready = start ~= nil and layout.finishGate ~= nil and #(layout.pathWaypoints or {}) >= 2
  local car = ac.getCar(0)
  local distance = nil
  if ready and car then
    local dx, dz = car.position.x - start.position.x, car.position.z - start.position.z
    distance = math.sqrt(dx * dx + dz * dz) - (start.radiusMeters or 0)
  end
  local inside = distance ~= nil and distance <= 0

  panel(p1, p2, ready and BRAND.accent or BRAND.accent2)
  if not ready then
    -- No run is possible here, so the rules would only be noise.
    textIn('SEM LAYOUT NESTA PISTA', 15, p1 + vec2(20, 18), vec2(p2.x - 20, p1.y + 44), 'Start', 'Center', BRAND.accent2, 'title')
    textIn('O admin ainda não publicou o layout.', 11, p1 + vec2(20, 46), vec2(p2.x - 16, p1.y + 66),
      'Start', 'Center', BRAND.muted, 'mono')
    return
  elseif inside then
    local center = vec2(p2.x - 34, p1.y + 22)
    local phase = (os.clock and os.clock() or 0) % 1
    pulseRing(center, 7, 8, phase, BRAND.accent)
    ui.drawCircleFilled(center, 5, BRAND.accent)
    textIn('BUZINA PARA COMEÇAR', 15, p1 + vec2(20, 8), vec2(p2.x - 52, p1.y + 34), 'Start', 'Center', BRAND.accent, 'title')
  else
    textIn('VAI ATÉ À PARTIDA', 15, p1 + vec2(20, 8), vec2(p2.x - 90, p1.y + 34), 'Start', 'Center', BRAND.text, 'title')
    textIn(distance and string.format('%.0f m', math.max(0, distance)) or '', 15,
      vec2(p2.x - 90, p1.y + 8), vec2(p2.x - 18, p1.y + 34), 'End', 'Center', BRAND.accent, 'monoBold')
  end

  -- Rules that void a run.
  fill(vec2(p1.x + 20, p1.y + 40), vec2(p2.x - 16, p1.y + 41), rgbm(1, 1, 1, 0.08), 0)
  textIn('A RUN É INCOMPLETA SE', 9, p1 + vec2(20, 44), vec2(p2.x - 16, p1.y + 56), 'Start', 'Center', BRAND.muted, 'mono')
  textIn('Arrancar antes · Contramão · Trompo', 10,
    p1 + vec2(20, 57), vec2(p2.x - 12, p1.y + 71), 'Start', 'Center', BRAND.text, 'mono')
  textIn('3 rodas fora · Parar · Deixar de derrapar', 10,
    p1 + vec2(20, 71), vec2(p2.x - 12, p1.y + 85), 'Start', 'Center', BRAND.text, 'mono')
  textIn('Toques, rodas fora e correções descontam', 9,
    p1 + vec2(20, 86), vec2(p2.x - 12, p1.y + 98), 'Start', 'Center', BRAND.muted, 'mono')
end

function M.hud(context, windowMode)
  local session = context.session
  local sim = ac.getSim()
  if not session:isBusy() and session.resultAge >= 4 then
    guide(context, windowMode and vec2(0, hudWindowTopPadding)
      or vec2(sim.windowWidth * 0.5 - hudWindowWidth * 0.5, sim.windowHeight - hudHeights.idle - 40))
    return
  end

  local width, height = M.hudSize(context)
  local p1 = windowMode
    and vec2(0, hudWindowTopPadding)
    or vec2(sim.windowWidth * 0.5 - width * 0.5, sim.windowHeight - height - 40)
  local p2 = p1 + vec2(width, height)
  local result = context.lastResult
  local accent = session.state == 'result' and result and not result.valid and BRAND.accent2 or BRAND.accent
  panel(p1, p2, accent)

  if session.state == 'countdown' then
    -- Text left, count right inside its pulsing ring.
    local center = vec2(p2.x - 46, p1.y + height * 0.5)
    -- countdownRemaining decreases, so its fractional part runs 1 -> 0 each
    -- second; inverted so the ring starts small and expands/fades instead.
    local phase = 1 - (session.countdownRemaining - math.floor(session.countdownRemaining))
    pulseRing(center, 20, 12, phase, accent)
    pulseRing(center, 20, 12, (phase + 0.5) % 1, accent)
    ui.drawCircle(center, 20, withAlpha(BRAND.text, 0.25), 40, 1.5)
    textIn('PREPARA-TE', 20, p1 + vec2(20, 12), p1 + vec2(200, 40), 'Start', 'Center', accent, 'title')
    textIn('ARRANCAR ANTES INVALIDA', 11, p1 + vec2(20, 42), p1 + vec2(200, 60), 'Start', 'Center', BRAND.muted, 'mono')
    -- Box nudged up a little: DWrite centers the line box, and digits sit
    -- low inside it.
    textIn(tostring(math.max(1, math.ceil(session.countdownRemaining))), 30,
      center - vec2(26, 29), center + vec2(26, 23), 'Center', 'Center', BRAND.text, 'number')

  elseif session.state == 'running' then
    local sample = session.samples[#session.samples]
    if sample then
      -- Angle is the headline number; speed sits beside it; the gauge on the
      -- right turns from lime to magenta as the angle passes the target.
      textIn(string.format('%.0f°', sample.angleDeg), 38, p1 + vec2(20, 4), p1 + vec2(118, 52), 'Start', 'Center', BRAND.text, 'number')
      textIn('ÂNGULO', 10, p1 + vec2(21, 48), p1 + vec2(118, 62), 'Start', 'Center', BRAND.muted, 'mono')
      textIn(string.format('%.0f', sample.speedKmh), 26, p1 + vec2(128, 12), p1 + vec2(210, 48), 'Start', 'Center', BRAND.text, 'number')
      -- A deduction (contact, tire off, correction) flashes where the speed label sits.
      local sinceDeduction = session.lastDeductionAt and (session.runElapsed * 1000 - session.lastDeductionAt) or math.huge
      if sinceDeduction < 1500 then
        local labels = { contact = 'TOQUE', tireOff = 'RODA FORA', straighten = 'CORREÇÃO' }
        textIn(string.format('%s -%d', labels[session.lastDeductionKind] or 'DEDUÇÃO', session.lastDeductionPoints or 0), 10,
          p1 + vec2(129, 48), p1 + vec2(214, 62), 'Start', 'Center', BRAND.accent2, 'monoBold')
      else
        textIn('KM/H', 10, p1 + vec2(129, 48), p1 + vec2(210, 62), 'Start', 'Center', BRAND.muted, 'mono')
      end
      angleGauge(vec2(p2.x - 44, p1.y + 34), 24, sample.angleDeg, 90,
        context.scoring.targetAngleDeg, rgbm(1, 1, 1, 0.12))
      -- Course progress along the bottom edge.
      local barY = p2.y - 5
      fill(vec2(p1.x + 16, barY), vec2(p2.x - 10, barY + 3), rgbm(1, 1, 1, 0.10), 2)
      fill(vec2(p1.x + 16, barY),
        vec2(p1.x + 16 + (width - 26) * U.clamp(sample.progress.normalized, 0, 1), barY + 3), accent, 2)
    end

  elseif result then
    if result.personalBest and session.resultAge < 0.8 then
      local phase = U.clamp(session.resultAge / 0.8, 0, 1)
      fill(p1, p2, withAlpha(BRAND.accent, (1 - phase) * 0.18), 4)
      speedBurst(vec2(p1.x + 52, p1.y + 60), phase, BRAND.accent)
    end
    textIn(result.personalBest and 'NOVO RECORDE' or (result.valid and 'RESULTADO' or 'RUN INCOMPLETA'),
      13, p1 + vec2(20, 6), p1 + vec2(220, 26), 'Start', 'Center', accent, 'title')
    textIn(string.format('%.0f', result.score or 0), 52, p1 + vec2(18, 26), p1 + vec2(130, 86), 'Start', 'Center', BRAND.text, 'number')
    textIn('PTS', 10, p1 + vec2(20, 82), p1 + vec2(80, 96), 'Start', 'Center', BRAND.muted, 'mono')
    if result.valid then
      -- Breakdown: name left, points / max right.
      local scoring = context.scoring or {}
      local rows = {
        { 'LINHA', string.format('%.0f/%d', result.line or 0, scoring.leadLinePoints or 35) },
        { 'ÂNGULO', string.format('%.0f/%d', result.angle or 0, scoring.leadAnglePoints or 35) },
        { 'ESTILO', string.format('%.0f/%d', result.styleSpeed or 0, scoring.leadStyleSpeedPoints or 30) },
      }
      -- Wall and car contacts get a fourth row, so the rows close up a little.
      local penalties = tonumber(result.penalties) or 0
      if penalties > 0 then
        local count = tonumber(result.deductionCount) or tonumber(result.contacts) or 0
        rows[#rows + 1] = { count == 1 and '1 DEDUÇÃO' or string.format('%d DEDUÇÕES', count),
          string.format('-%.0f', penalties), BRAND.accent2 }
      end
      local first, step = #rows > 3 and 24 or 30, #rows > 3 and 18 or 20
      for index, row in ipairs(rows) do
        local top = p1.y + first + (index - 1) * step
        textIn(row[1], 11, vec2(p1.x + 150, top), vec2(p2.x - 46, top + 18), 'Start', 'Center', row[3] or BRAND.muted, 'title')
        textIn(row[2], 12, vec2(p1.x + 210, top), vec2(p2.x - 16, top + 18), 'End', 'Center', row[3] or BRAND.text, 'monoBold')
      end
    else
      -- Voided: the reason is what the driver needs.
      textIn(tostring(result.reason or ''), 15, p1 + vec2(140, 30), vec2(p2.x - 16, p1.y + 84),
        'Start', 'Center', BRAND.text, 'title')
    end
  end
end

-- Compact on-screen leaderboard: best run per driver this session on this
-- track. Shows the top rows; if the local driver is further down, the last
-- row is theirs, so they always see where they stand.
local leaderboardWidth, leaderboardMaxRows = 264, 8
local leaderboardHeader, leaderboardRow = 32, 20

M.windowTopPadding = hudWindowTopPadding

local function visibleLeaderboardRows(entries, ownName)
  local rows, ownIndex = {}, nil
  for index, entry in ipairs(entries) do
    if entry.name == ownName then ownIndex = index end
  end
  for index = 1, math.min(#entries, leaderboardMaxRows) do
    rows[#rows + 1] = { position = index, entry = entries[index] }
  end
  if ownIndex and ownIndex > leaderboardMaxRows then
    rows[#rows] = { position = ownIndex, entry = entries[ownIndex] }
  end
  return rows
end

function M.leaderboardSize(entries)
  local count = math.max(1, math.min(#entries, leaderboardMaxRows))
  return leaderboardWidth, leaderboardHeader + count * leaderboardRow + 10
end

---@param entries {name: string, score: number, valid: boolean}[] @Best first, from Leaderboard.entries().
---@param origin vec2 @Top-left corner of the panel.
function M.leaderboard(context, entries, origin)
  local width, height = M.leaderboardSize(entries)
  local p1, p2 = origin, origin + vec2(width, height)
  fill(p1, p2, BRAND.panelBg, 4)
  accentStripe(p1, vec2(p1.x, p2.y), BRAND.accent)
  textIn('CLASSIFICAÇÃO', 13, p1 + vec2(20, 6), p1 + vec2(140, 28), 'Start', 'Center', BRAND.accent, 'title')
  textIn(context.trackName or context.track or '', 11, p1 + vec2(140, 6), vec2(p2.x - 12, p1.y + 28),
    'End', 'Center', BRAND.muted, 'mono')

  if #entries == 0 then
    textIn('Ainda sem runs nesta sessão.', 12, p1 + vec2(20, leaderboardHeader),
      vec2(p2.x - 12, p1.y + leaderboardHeader + leaderboardRow), 'Start', 'Center', BRAND.muted, 'mono')
    return
  end

  local ownName = U.call(ac.getDriverName, nil, 0)
  for index, row in ipairs(visibleLeaderboardRows(entries, ownName)) do
    local top = p1.y + leaderboardHeader + (index - 1) * leaderboardRow
    local entry = row.entry
    if entry.name == ownName then
      fill(vec2(p1.x + 12, top), vec2(p2.x - 6, top + leaderboardRow), withAlpha(BRAND.accent, 0.12), 2)
    end
    textIn(tostring(row.position), 12, vec2(p1.x + 14, top), vec2(p1.x + 36, top + leaderboardRow),
      'End', 'Center', row.position == 1 and BRAND.accent or BRAND.muted, 'monoBold')
    textIn(entry.name, 13, vec2(p1.x + 46, top), vec2(p2.x - 74, top + leaderboardRow),
      'Start', 'Center', entry.valid and BRAND.text or BRAND.muted, 'title')
    textIn(entry.valid and string.format('%.1f', entry.score or 0) or '—', 13,
      vec2(p2.x - 72, top), vec2(p2.x - 14, top + leaderboardRow),
      'End', 'Center', entry.valid and BRAND.text or BRAND.accent2, 'monoBold')
  end
end

return M

end

__bundled["src.ui_app"] = function()
local U = require('src.util')
local G = require('src.geometry')
local Model = require('src.model')
local Profiles = require('src.profiles')
local M = {}

-- Palette pulled from driftfactory.pt (background/text/lime accent/magenta
-- accent), used for the leaderboard and score displays specifically.
local BRAND = {
  accent = rgbm(212 / 255, 255 / 255, 63 / 255, 1), -- lime
  accent2 = rgbm(255 / 255, 62 / 255, 200 / 255, 1), -- magenta, used for invalid/attention
  text = rgbm(243 / 255, 244 / 255, 239 / 255, 1), -- cream
  muted = rgbm(154 / 255, 160 / 255, 172 / 255, 1),
}

local function heading(value)
  ui.textColored(value, rgbm(0.25, 0.8, 1, 1))
  ui.separator()
end

local function muted(value)
  ui.textColored(value, rgbm(0.68, 0.72, 0.76, 1))
end

local function wrapped(value)
  if ui.textWrapped then ui.textWrapped(value) else ui.text(value) end
end

local function checkbox(label, value)
  local ok, changed = pcall(ui.checkbox, label, value)
  if ok and changed then return not value, true end
  return value, false
end

local function slider(label, value, minimum, maximum, format)
  local ok, result, changed = pcall(ui.slider, label, value, minimum, maximum, format)
  if ok and type(result) == 'number' then return result, changed end
  return value, false
end

local function sameLine()
  if ui.sameLine then ui.sameLine() end
end

local function scoreLine(label, value)
  ui.text(string.format('%-18s %6.1f', label, value or 0))
end

local function saveWarning(context, message)
  if not context.dirty then return end
  ui.textColored(message or 'ALTERAÇÕES NÃO GUARDADAS - clica em Guardar Layout Agora para as manter depois de recarregar.',
    rgbm(1, 0.18, 0.12, 1))
  if ui.button('Guardar Layout Agora') then context:saveLayout() end
end

local function environment(context)
  local sim = ac.getSim()
  if sim.isReplayActive then
    ui.textColored('Desativado em replay', rgbm(1, 0.3, 0.2, 1))
    return false
  end
  -- Online (or anywhere CSP withholds physics write access), the app can
  -- still judge a run, it just can't auto-align the car to the start line
  -- itself — see CREDITS.md.
  if sim.isOnlineRace or not physics.allowed() then
    ui.textColored('Online: alinhamento manual', rgbm(0.85, 0.75, 0.2, 1))
    wrapped('A app não consegue alinhar o carro automaticamente aqui — alinha-te tu mesmo na partida e depois buzina.')
  end
  return true
end

local function runTab(context)
  heading('Sessão Atual')
  ui.text('Pista: ' .. context.track .. ' / ' .. context.layoutID)
  ui.text('Carro: ' .. context.carID)
  local sourceLabels = {
    ['local'] = 'Layout local (edição)',
    official = 'Layout oficial',
    ['official-cached'] = 'Layout oficial (cópia guardada)',
    ['official-missing'] = 'Layout oficial indisponível',
  }
  muted(sourceLabels[context.layoutSource] or '')
  if context.layoutStatus then muted(context.layoutStatus) end
  local available = environment(context)
  local errors = Model.validateLayout(context.layout)
  if context.layoutSource == 'official-missing' then
    -- Not something the player can fix by editing — the track just hasn't
    -- been published yet (or the download hasn't finished).
    ui.newLine()
    ui.textColored('Ainda não há layout para esta pista.', rgbm(1, 0.65, 0.2, 1))
  elseif #errors > 0 then
    ui.newLine()
    ui.textColored('O layout não está pronto:', rgbm(1, 0.65, 0.2, 1))
    for _, errorMessage in ipairs(errors) do ui.bulletText(errorMessage) end
  elseif available then
    ui.newLine()
    ui.textColored('Pronto para uma run a solo', rgbm(0.2, 1, 0.35, 1))
    wrapped(physics.allowed()
      and 'Conduz até ao círculo verde de partida e buzina. A app alinha o carro e começa uma contagem decrescente de cinco segundos. Arrancar antes do zero invalida a run.'
      or 'Para dentro do círculo verde de partida, virado para o percurso, e buzina. Começa uma contagem decrescente de cinco segundos. Arrancar antes do zero invalida a run.')
    context.showCourse = select(1, checkbox('Mostrar zonas e clips na pista', context.showCourse))
    local car = ac.getCar(0)
    if car and context.layout.leadStart then
      local inside = G.insideCircle(
        U.fromVec3(car.position), context.layout.leadStart.position, context.layout.leadStart.radiusMeters)
      ui.textColored(inside and 'Na zona de partida' or 'Conduz até à zona de partida',
        inside and rgbm(0.2, 1, 0.35, 1) or rgbm(0.85, 0.85, 0.85, 1))
    end
  end
  if context.session:isBusy() and ui.button('Cancelar Run Atual') then
    context.session:cancel('Run cancelada pelo jogador.')
  end

  ui.newLine()
  heading('Objetivos de Pontuação')
  scoreLine('Velocidade alvo', context.scoring.targetSpeedKmh)
  scoreLine('Ângulo alvo', context.scoring.targetAngleDeg)
  scoreLine('Ângulo mínimo', context.scoring.minimumAngleDeg)
  scoreLine('Ângulo de estilo (início)', context.scoring.styleMinimumDriftAngleDeg)
  scoreLine('Ângulo de estilo (total)', context.scoring.styleFullDriftAngleDeg)

  ui.newLine()
  heading('Classificação')
  local showLeaderboard, leaderboardChanged = checkbox('Mostrar a classificação no ecrã', context.showLeaderboard)
  if leaderboardChanged then context:setShowLeaderboard(showLeaderboard) end
  muted('Melhor run de cada piloto nesta sessão, no canto do ecrã.')
  muted('Partilhada entre jogadores, não validada pelo servidor.')

  ui.newLine()
  heading('Pontuação (Drift Masters 2026)')
  ui.bulletText('Linha 60: zonas exteriores e clips, cada um vale o mesmo')
  ui.bulletText('Ângulo 20: ângulo alto e mantido nas zonas julgadas')
  ui.bulletText('Estilo 20: iniciação 5 · fluidez 10 · compromisso 5')

  ui.newLine()
  heading('Deduções')
  ui.bulletText('Toque num muro ou carro: -5 · -10 (perdes 5 km/h) · -20 (15 km/h)')
  ui.bulletText('Roda fora da pista (1 ou 2 rodas): -5')
  ui.bulletText('Endireitar por instantes (correção): -5')
  ui.bulletText('Dupla iniciação: 0 pontos de iniciação')
  muted('Zonas e clips falhados, fora da linha e falta de ângulo saem da própria pontuação.')

  ui.newLine()
  heading('A Run Fica Incompleta Se')
  ui.bulletText('Arrancares antes do fim da contagem')
  ui.bulletText('Fizeres um trompo')
  ui.bulletText('Deixares de derrapar (1 s direito)')
  ui.bulletText('Saíres com três rodas da pista')
  ui.bulletText('Andares no sentido contrário ou parares o carro')

  ui.newLine()
  heading('Recorde Pessoal')
  if context.results.personalBest then
    local best = context.results.personalBest
    ui.textColored(string.format('%.1f pontos', best.score), BRAND.accent)
    muted(U.formatDate(best.dateUtc))
    scoreLine('Linha', best.line)
    scoreLine('Ângulo', best.angle)
    scoreLine('Estilo', best.styleSpeed)
  else
    muted('Ainda sem recorde pessoal válido.')
  end
end

local function editorTab(context)
  local editor, layout = context.editor, context.layout
  editor.debug = select(1, checkbox('Modo de Depuração', editor.debug))

  ui.newLine()
  heading('Ficheiro de Layout')
  ui.text(context.dirty and '* Alterações não guardadas' or 'Guardado')
  if ui.button('Guardar Layout') then context:saveLayout() end
  sameLine()
  if ui.button('Reverter') then context:reloadLayout() end
  sameLine()
  if ui.button('Desfazer') then editor:undoLast() end
  if ui.button('Importar JSON') then
    context.storage:importLayout(function(ok, value)
      if ok then
        context.layout = value
        context.dirty = true
        context:refreshScoring()
        context.status = 'Layout importado. Guarda para o manter na biblioteca local.'
      else
        context.status = tostring(value)
      end
    end)
  end
  sameLine()
  if ui.button('Exportar JSON') then
    context.storage:exportLayout(layout, function(_, message) context.status = tostring(message) end)
  end

  if context.session:isBusy() or context.calibration.active then
    ui.newLine()
    ui.textColored('A edição está desativada durante uma run ou sessão de calibração.', rgbm(1, 0.65, 0.2, 1))
    return
  end

  ui.newLine()
  heading('Partida e Chegada')
  editor.startRadius = select(1, slider('Raio de partida', editor.startRadius, 1, 10, '%.1f m'))
  if ui.button('Capturar Partida') then editor:captureLeadStart() end
  if layout.leadStart then
    sameLine()
    if ui.button('Aplicar Raio de Partida') then
      editor:pushUndo()
      layout.leadStart.radiusMeters = editor.startRadius
      editor:changed('Raio de partida atualizado.')
    end
  end
  editor.finishWidth = select(1, slider('Largura da chegada', editor.finishWidth, 4, 30, '%.1f m'))
  if ui.button('Capturar Gate de Chegada') then editor:captureFinish() end

  ui.newLine()
  heading('Rota')
  if ui.button(editor.recording and 'Parar Gravação' or 'Gravar Rota') then editor:toggleRecording() end
  sameLine()
  if ui.button(editor.mode == 'route' and 'Parar Edição da Rota' or 'Editar Rota') then editor:setMode('route') end
  sameLine()
  if ui.button('Limpar Rota') then editor:clearRoute() end
  editor.routeSmoothRadius = select(1, slider('Raio de suavização', editor.routeSmoothRadius, 5, 30, '%.1f m'))
  local width, widthChanged = slider(
    'Meia-largura da rota', layout.pathCorridorHalfWidthMeters, 1, 10, '%.1f m')
  if widthChanged then
    editor:pushUndo()
    layout.pathCorridorHalfWidthMeters = width
    editor:changed('Largura da rota atualizada.')
  end
  muted(string.format('%d pontos de rota. Ctrl+click insere; arrastar move; Shift+arrastar suaviza; botão direito remove.',
    #layout.pathWaypoints))

  ui.newLine()
  heading('Zonas Exteriores')
  if ui.button(editor.mode == 'outer' and 'Parar Ferramenta Exterior' or 'Desenhar / Editar Exterior') then editor:setMode('outer') end
  sameLine()
  if ui.button('Terminar Rascunho') then editor:finishOuter() end
  sameLine()
  if ui.button('Cancelar Rascunho') then editor:cancelOuter() end
  muted(string.format('%d zonas, %d pontos em rascunho. Ctrl+click coloca ou insere pontos.',
    #layout.outerZones, #editor.outerDraft))

  ui.newLine()
  heading('Clips Interiores')
  editor.clipRadius = select(1, slider('Raio do clip', editor.clipRadius, 0.5, 8, '%.1f m'))
  if ui.button(editor.mode == 'clip' and 'Parar Ferramenta de Clips' or 'Colocar / Remover Clips') then editor:setMode('clip') end
  muted(string.format('%d clips. Ctrl+click coloca; botão direito remove.', #layout.innerClips))

  ui.newLine()
  heading('Visibilidade do Editor')
  wrapped('Zonas e clips desmarcados ficam escondidos e não podem ser selecionados. Isto afeta só a tua vista no editor.')
  if #layout.outerZones > 0 then
    ui.text('Zonas exteriores')
    for index = 1, #layout.outerZones do
      local visible, changed = checkbox(
        'Exterior ' .. tostring(index) .. '##outerVisibility' .. tostring(index),
        editor:isOuterZoneVisible(index))
      if changed then editor:setOuterZoneVisible(index, visible) end
      if index % 3 ~= 0 and index < #layout.outerZones then sameLine() end
    end
  end
  if #layout.innerClips > 0 then
    ui.text('Clips interiores')
    for index = 1, #layout.innerClips do
      local visible, changed = checkbox(
        'Clip ' .. tostring(index) .. '##clipVisibility' .. tostring(index),
        editor:isInnerClipVisible(index))
      if changed then editor:setInnerClipVisible(index, visible) end
      if index % 3 ~= 0 and index < #layout.innerClips then sameLine() end
    end
  end
end

local labels = {
  targetSpeedKmh = 'Velocidade alvo',
  targetAngleDeg = 'Ângulo alvo',
  minimumAngleDeg = 'Ângulo mínimo',
  styleMinimumDriftAngleDeg = 'Ângulo mínimo de estilo',
  styleFullDriftAngleDeg = 'Ângulo total de estilo'
}

local ranges = {
  targetSpeedKmh = { 20, 250, '%.0f km/h' },
  targetAngleDeg = { 20, 100, '%.0f deg' },
  minimumAngleDeg = { 0, 80, '%.0f deg' },
  styleMinimumDriftAngleDeg = { 0, 80, '%.0f deg' },
  styleFullDriftAngleDeg = { 5, 100, '%.0f deg' }
}

local function selectedProfileTarget(context)
  local packPattern, packName = Profiles.detectPackPattern(context.carID)
  if context.profileScope ~= 'exact' and context.profileScope ~= 'pack' then
    context.profileScope = packPattern and 'pack' or 'exact'
  elseif context.profileScope == 'pack' and not packPattern then
    context.profileScope = 'exact'
  end
  if context.profileScope == 'pack' and packPattern then
    return {
      scope = 'pack',
      pattern = packPattern,
      name = packName,
      heading = 'Perfil de Pack',
      description = 'Aplica-se a todos os carros que correspondam a ' .. packPattern .. '.'
    }
  end
  return {
    scope = 'exact',
    pattern = context.carID,
    name = context.carID,
    heading = 'Perfil Exato do Carro',
    description = 'Aplica-se só a este carro exato.'
  }
end

local function setProfileOverride(context, target, field, value)
  Profiles.setOverrideForPattern(context.layout, target.pattern, target.name, field, value)
  context.dirty = true
  context:refreshScoring()
end

local function applyRecommendation(context, pattern, name, recommendation)
  for _, field in ipairs(Profiles.overrideFields) do
    Profiles.setOverrideForPattern(context.layout, pattern, name, field, recommendation[field])
  end
  context.dirty = true
  context:refreshScoring()
end

local function carSetupTab(context)
  heading('Âmbito do Perfil')
  ui.text(context.carID)
  local packPattern, packName = Profiles.detectPackPattern(context.carID)
  if packPattern then
    if ui.button((context.profileScope == 'pack' and '* ' or '') .. 'Editar Pack ' .. packPattern) then
      context.profileScope = 'pack'
    end
    sameLine()
  else
    muted('Nenhum prefixo de pack detetado. IDs de carro como VDC_* ou SWARM_* podem usar perfis de pack.')
  end
  if ui.button((context.profileScope == 'exact' and '* ' or '') .. 'Editar Carro Exato') then
    context.profileScope = 'exact'
  end

  local target = selectedProfileTarget(context)
  ui.newLine()
  heading(target.heading)
  ui.text(target.pattern)
  muted(target.description)
  saveWarning(context, 'ALTERAÇÕES DE OVERRIDE NÃO GUARDADAS - clica em Guardar Layout Agora para manter/aplicar este perfil depois de recarregar.')
  local profile = Profiles.findPattern(context.layout, target.pattern)
  if not profile then
    muted('Ainda sem overrides guardados para este âmbito. Ativar um cria o perfil.')
  end
  local inherited = Profiles.resolveInherited(context.layout, context.carID, target.pattern)
  for _, field in ipairs(Profiles.overrideFields) do
    profile = Profiles.findPattern(context.layout, target.pattern)
    local active = profile and profile.overrides[field] ~= nil or false
    local newActive, changed = checkbox('Substituir ' .. labels[field], active)
    if changed then
      if newActive then
        setProfileOverride(context, target, field, inherited[field])
      else
        setProfileOverride(context, target, field, nil)
      end
      profile = Profiles.findPattern(context.layout, target.pattern)
      inherited = Profiles.resolveInherited(context.layout, context.carID, target.pattern)
    end
    local value = newActive and profile and profile.overrides[field] or inherited[field]
    if newActive then
      local range = ranges[field]
      local newValue, valueChanged = slider(labels[field] .. '##' .. field, value, range[1], range[2], range[3])
      if valueChanged then
        setProfileOverride(context, target, field, newValue)
      end
    else
      muted(string.format('%s herdado: %.1f', labels[field], inherited[field]))
    end
  end
  local ok, errorMessage = Profiles.validate(context.scoring)
  if not ok then ui.textColored(errorMessage, rgbm(1, 0.3, 0.2, 1)) end
end

local function calibrationTab(context)
  local calibration = context.calibration
  heading('Calibração de Cinco Runs')
  wrapped('A calibração usa cinco runs válidas e cria recomendações a partir das três melhores. As tentativas não são adicionadas ao histórico normal.')
  if not calibration.active then
    if ui.button('Iniciar Calibração') then
      calibration:start()
      context.status = 'Calibração iniciada. Completa cinco runs válidas.'
    end
  else
    ui.text(string.format('Runs válidas: %d / 5', #calibration.validRuns))
    ui.text(string.format('Tentativas: %d', #calibration.attempts))
    if ui.button('Reiniciar Calibração') then
      context.session:cancel('Run de calibração cancelada.')
      calibration:start()
    end
    sameLine()
    if ui.button('Cancelar Calibração') then
      context.session:cancel('Run de calibração cancelada.')
      calibration:cancel()
    end
  end
  if calibration.recommendation then
    ui.newLine()
    heading('Recomendação')
    local recommendation = calibration.recommendation
    scoreLine('Velocidade alvo', recommendation.targetSpeedKmh)
    scoreLine('Ângulo alvo', recommendation.targetAngleDeg)
    scoreLine('Ângulo mínimo', recommendation.minimumAngleDeg)
    scoreLine('Mínimo de estilo', recommendation.styleMinimumDriftAngleDeg)
    scoreLine('Total de estilo', recommendation.styleFullDriftAngleDeg)
    local packPattern, packName = Profiles.detectPackPattern(context.carID)
    if packPattern and ui.button('Aplicar ao Pack ' .. packPattern) then
      applyRecommendation(context, packPattern, packName, recommendation)
      calibration:cancel()
      context.status = 'Calibração aplicada a ' .. packPattern .. '. Guarda o layout para a manter.'
    end
    if packPattern then sameLine() end
    if ui.button('Aplicar ao Carro Atual') then
      applyRecommendation(context, context.carID, context.carID, recommendation)
      calibration:cancel()
      context.status = 'Calibração aplicada ao perfil do carro atual. Guarda o layout para a manter.'
    end
    sameLine()
    if ui.button('Rejeitar Recomendação') then calibration:cancel() end
  end
end

local function resultsTab(context)
  heading('Resultados Locais')
  if context.results.personalBest then
    ui.textColored(string.format('PB %.1f pontos', context.results.personalBest.score), BRAND.accent)
  else
    muted('Sem recorde pessoal.')
  end
  sameLine()
  if ui.button('Limpar Resultados') then
    local ok, err = context.storage:clearResults(context.results)
    context.status = ok and 'Resultados limpos.' or tostring(err)
  end
  ui.separator()
  if #context.results.runs == 0 then muted('Ainda sem runs completas.') return end
  for index, run in ipairs(context.results.runs) do
    local title = string.format('#%d  %s  %.1f pts  %s',
      index, run.valid and 'VÁLIDA' or 'INVÁLIDA', run.score or 0, U.formatDate(run.dateUtc))
    ui.treeNode(title, function()
      ui.text('Motivo: ' .. tostring(run.reason))
      scoreLine('Linha', run.line)
      scoreLine('Ângulo', run.angle)
      scoreLine('Estilo', run.styleSpeed)
      scoreLine('Ângulo médio', run.averageAngle)
      scoreLine('Velocidade média', run.averageSpeed)
      scoreLine('Qualidade da rota', run.pathQuality)
      scoreLine('Qualidade da zona', run.zoneQuality)
      scoreLine('Qualidade do clip', run.clipQuality)
    end)
  end
end

function M.window(context)
  local sim = ac.getSim()
  local isAdmin = sim and sim.isAdmin == true
  -- Everything that changes what a run is judged against (layout, scoring
  -- targets, calibration) is admin-only once online — otherwise any player
  -- could lower their own targets and inflate what they broadcast to the
  -- shared leaderboard. Offline there's no one else to restrict.
  -- The server-delivered version can't save files, so editing stays in the
  -- installed app regardless of admin status.
  local canEdit = not context.editingDisabled and (isAdmin or not (sim and sim.isOnlineRace))

  ui.textColored('Drift Factory Judge App', rgbm(0.25, 0.8, 1, 1))
  sameLine()
  muted('v0.3.0')
  if isAdmin then
    sameLine()
    ui.textColored('ADMIN', BRAND.accent)
  end
  muted('Modificado, não oficial — baseado em DriftJudging SP')
  muted('por DeadEndReece (AGPL-3.0). Código, créditos e licença:')
  muted('github.com/insidedacoolest/drift-jury')
  if context.status and context.status ~= '' then
    ui.textWrapped(context.status)
    ui.separator()
  end
  if canEdit then
    saveWarning(context)
    if context.dirty then ui.separator() end
  end
  ui.tabBar('DriftFactoryJudgeAppTabs', function()
    ui.tabItem('Corrida', function() runTab(context) end)
    if canEdit then
      ui.tabItem('Editor de Layout', function() editorTab(context) end)
      ui.tabItem('Configuração do Carro', function() carSetupTab(context) end)
      ui.tabItem('Calibração', function() calibrationTab(context) end)
    end
    ui.tabItem('Resultados', function() resultsTab(context) end)
  end)
end

return M

end

__bundled["src.context"] = function()
-- The judging session's shared state (track, layout, scoring, results,
-- session and editor), used by both the installed app and the
-- server-delivered online script. Each entry point supplies its own
-- storage, since online scripts can't write files.
local U = require('src.util')
local D = require('src.defaults')
local Model = require('src.model')
local Profiles = require('src.profiles')
local OfficialLayout = require('src.official_layout')
local Calibration = require('src.calibration')
local Session = require('src.session')
local Editor = require('src.editor')

local function currentLayout()
  local value = U.call(ac.getTrackLayout, '')
  return value == '' and 'open' or value
end

local function isOnline()
  local sim = ac.getSim()
  return sim ~= nil and sim.isOnlineRace == true
end

local Context = {}
Context.__index = Context
Context.isOnline = isOnline

---@param options {createStorage: fun(track: string, layoutID: string, carID: string): table, editingDisabled: boolean?}
function Context.new(options)
  local track = U.call(ac.getTrackID, U.call(ac.getTrackName, 'unknown'))
  local layoutID = currentLayout()
  local carID = U.call(function() return ac.getCarID(0) end, 'unknown-car')
  local storage = options.createStorage(track, layoutID, carID)
  -- Online, only the official (published) layout counts, so everyone on
  -- the server is judged the same way: start from the last downloaded copy
  -- and replace it once the fresh download lands. Offline, the player's own
  -- editable layout is used, for preparing tracks.
  local layout, layoutWarning, layoutSource
  if isOnline() then
    layout = storage:loadOfficialCache()
    layoutSource = layout and 'official-cached' or 'official-missing'
    layout = layout or Model.normalizeLayout(D.newLayout(track, layoutID), track, layoutID)
  else
    layout, layoutWarning = storage:loadLayout()
    layoutSource = 'local'
  end
  local results, resultWarning = storage:loadResults()
  local hudSettings = storage:loadHudSettings()
  local self = setmetatable({
    track = track,
    trackName = U.call(ac.getTrackName, track),
    layoutID = layoutID,
    carID = carID,
    storage = storage,
    -- Set by the server-delivered version: it has no file access, so layout
    -- editing, calibration and car setup stay in the installed app.
    editingDisabled = options.editingDisabled == true,
    -- Player-side toggle to draw outer zones and clips on track (start and
    -- finish are always drawn).
    showCourse = false,
    -- On-screen leaderboard (top-right corner); on unless the player turned it off.
    showLeaderboard = hudSettings.showLeaderboard ~= false,
    layout = layout,
    layoutSource = layoutSource, -- 'local' | 'official' | 'official-cached' | 'official-missing'
    layoutStatus = nil, -- message about the official download, shown in the run tab
    pendingOfficialLayout = nil,
    results = results,
    hudSettings = hudSettings,
    scoring = nil,
    matchedProfile = nil,
    dirty = false,
    status = layoutWarning or resultWarning or '',
    lastResult = results.runs[1],
    calibration = Calibration.new()
  }, Context)
  self:refreshScoring()
  self.session = Session.new(self)
  self.editor = Editor.new(self)
  if isOnline() then self:fetchOfficialLayout() end
  return self
end

function Context:setShowLeaderboard(show)
  if self.showLeaderboard == show then return end
  self.showLeaderboard = show
  self.hudSettings.showLeaderboard = show
  self.storage:saveHudSettings(self.hudSettings)
end

function Context:refreshScoring()
  self.scoring, self.matchedProfile = Profiles.resolve(self.layout, self.carID)
end

function Context:fetchOfficialLayout()
  self.layoutStatus = 'A descarregar o layout oficial…'
  OfficialLayout.fetch(self.track, self.layoutID, function(layout, message)
    if not layout then
      self.layoutStatus = message
      return
    end
    self.storage:saveOfficialCache(layout)
    self.pendingOfficialLayout = layout
    self.layoutStatus = nil
  end)
end

-- Swapping the layout mid-run would break progress tracking and scoring, so
-- a download that lands during a run waits until the run is over.
function Context:applyPendingOfficialLayout()
  if not self.pendingOfficialLayout or self.session:isBusy() then return end
  self.layout = self.pendingOfficialLayout
  self.pendingOfficialLayout = nil
  self.layoutSource = 'official'
  self.dirty = false
  self.editor.outerDraft = {}
  self.editor.undo = {}
  self:refreshScoring()
end

function Context:saveLayout()
  local errors = Model.validateLayout(self.layout)
  local scoringValid, scoringError = Profiles.validate(self.scoring)
  if not scoringValid then errors[#errors + 1] = 'Carro atual: ' .. scoringError end
  if #errors > 0 then
    self.status = 'Não é possível guardar: ' .. table.concat(errors, ' ')
    return
  end
  local ok, err = self.storage:saveLayout(self.layout)
  if ok then
    self.dirty = false
    self.status = 'Layout guardado.'
  else
    self.status = 'Falha ao guardar: ' .. tostring(err)
  end
end

function Context:reloadLayout()
  if self.session:isBusy() then
    self.status = 'Termina ou cancela a run atual antes de reverter.'
    return
  end
  if isOnline() then
    self:fetchOfficialLayout()
    self.status = 'A voltar ao layout oficial…'
    return
  end
  local layout, warning = self.storage:loadLayout()
  self.layout = layout
  self.dirty = false
  self.editor.outerDraft = {}
  self.editor.undo = {}
  self:refreshScoring()
  self.status = warning or 'Layout revertido.'
end

return Context

end

__bundled["src.storage_online"] = function()
-- Storage for the server-delivered online script. Online scripts can't write
-- files, so everything goes through ac.storage (CSP's own key-value store,
-- kept per player under Documents\Assetto Corsa\cfg\extension\state\lua).
-- Same interface as src/storage.lua; layout editing, import and export are
-- not available here and stay in the installed app.
local U = require('src.util')
local D = require('src.defaults')
local Model = require('src.model')
local Results = require('src.results')
local M = {}
M.__index = M

local unavailable = 'Não disponível na versão do servidor. Usa a app instalada, offline.'

local function key(...)
  local parts = {}
  for index, part in ipairs({ ... }) do parts[index] = U.sanitizePart(part) end
  return table.concat(parts, '/')
end

local function load(storageKey)
  local ok, content = pcall(function() return ac.storage[storageKey] end)
  if not ok or type(content) ~= 'string' or content == '' then return nil end
  return U.decodeJson(content)
end

local function save(storageKey, value)
  local encoded, encodeError = U.encodeJson(value)
  if not encoded then return false, encodeError end
  local ok, err = pcall(function() ac.storage[storageKey] = encoded end)
  if not ok then return false, tostring(err) end
  return true
end

function M.new(track, layoutID, carID)
  return setmetatable({
    track = track,
    layoutID = layoutID,
    carID = carID,
    officialKey = 'official:' .. key(track, layoutID),
    resultsKey = 'results:' .. key(track, layoutID, carID),
    hudKey = 'hud',
  }, M)
end

function M:loadLayout()
  return Model.normalizeLayout(D.newLayout(self.track, self.layoutID), self.track, self.layoutID), nil
end

function M:saveLayout()
  return false, unavailable
end

function M:loadOfficialCache()
  local loaded = load(self.officialKey)
  return loaded and Model.normalizeLayout(loaded, self.track, self.layoutID) or nil
end

function M:saveOfficialCache(layout)
  save(self.officialKey, Model.toStorageLayout(layout))
end

function M:loadResults()
  return Results.normalize(load(self.resultsKey), self.track, self.layoutID, self.carID), nil
end

function M:saveResults(results)
  return save(self.resultsKey, results)
end

function M:loadHudSettings()
  local loaded = load(self.hudKey)
  return type(loaded) == 'table' and loaded or { version = 1 }
end

function M:saveHudSettings(settings)
  settings.version = 1
  return save(self.hudKey, settings)
end

function M:addResult(results, score)
  local record = Results.add(results, score, self.track, self.layoutID, self.carID)
  local ok, saveError = self:saveResults(results)
  return ok, ok and record or saveError
end

function M:clearResults(results)
  Results.clear(results)
  return self:saveResults(results)
end

function M:importLayout(callback)
  if callback then callback(false, unavailable) end
end

function M:exportLayout(_, callback)
  if callback then callback(false, unavailable) end
end

return M

end

-- online/main.lua
-- Drift Factory Judge App — server-delivered version (CSP online script).
--
-- The server's CSP extra options load the bundled online/driftfactory.lua
-- (built from this file plus ac-lua/DriftFactoryJudgeApp/src by
-- online/build.lua), so players get the judge just by joining. Same
-- judging, scoring, official layouts and leaderboard as the installed app;
-- layout editing, calibration and car setup stay in the installed app,
-- since online scripts can't save files.
--
-- A modified version of DriftJudging SP by DeadEndReece, AGPL-3.0 with
-- additional attribution terms — see ac-lua/DriftFactoryJudgeApp/CREDITS.md
-- and LICENSE.md in github.com/insidedacoolest/drift-jury.

local Context = require('src.context')
local OnlineStorage = require('src.storage_online')
local Draw = require('src.draw')
local UI = require('src.ui_app')
local Leaderboard = require('src.leaderboard')

local FONTS_URL = 'https://raw.githubusercontent.com/insidedacoolest/drift-jury/master/online/fonts.zip'

local context = Context.new({
  createStorage = function(track, layoutID, carID) return OnlineStorage.new(track, layoutID, carID) end,
  editingDisabled = true,
})

-- Brand fonts: CSP downloads and caches the zip itself; until it lands (or
-- if it can't), the HUD uses CSP's default font.
if web and web.loadRemoteAssets then
  pcall(web.loadRemoteAssets, FONTS_URL, function(err, folder)
    if (not err or err == '') and folder and folder ~= '' then Draw.setFontsDir(folder) end
  end)
end

-- Main window: opened from the online extras menu in CSP's chat app
-- (lightbulb icon), as a tool window that stays on screen.
ui.registerOnlineExtra(ui.Icons.Speedometer, 'Drift Factory Judge', nil,
  function() UI.window(context) end, nil,
  ui.OnlineExtraFlags.Tool, ui.WindowFlags.None, vec2(400, 520))

function script.update(dt)
  dt = tonumber(dt) or 0
  context:applyPendingOfficialLayout()
  context.session:update(dt)
end

function script.draw3D()
  Draw.layout(context)
end

-- Drawn straight onto the screen: the session leaderboard in the top-right
-- corner (unless turned off in the run tab), and the score HUD at the bottom
-- center during the countdown, the run and for a few seconds after.
function script.drawUI()
  if context.showLeaderboard then
    local entries = Leaderboard.entries()
    local width = Draw.leaderboardSize(entries)
    Draw.leaderboard(context, entries, vec2(ac.getSim().windowWidth - width - 24, 24))
  end
  Draw.hud(context, false)
end
